# --- COMMONS CHILD LIMIT v2 --- a program a check starts has a memory ceiling too
import os, signal, subprocess, sys, threading

_CHILD_MIB = 1024      # how much memory a program started by a check, and what it starts, may use before it is stopped
_CHILD_OUTPUT_MIB = 64  # how much it may print (stdout and stderr together) before it is stopped


def _group_mib(pgid: int) -> float:
    """Resident memory, in MiB, of every process in the process group `pgid` (Linux: /proc; macOS: ps)."""
    pages = kib = 0
    try:
        if os.path.isdir("/proc/self"):
            for entry in os.listdir("/proc"):
                if entry.isdigit():
                    try:
                        with open(f"/proc/{entry}/stat") as f:
                            fields = f.read().rsplit(")", 1)[1].split()
                        if int(fields[2]) == pgid:
                            with open(f"/proc/{entry}/statm") as f:
                                pages += int(f.read().split()[1])
                    except (OSError, ValueError, IndexError):
                        continue
            return pages * os.sysconf("SC_PAGE_SIZE") / 2**20
        listing = subprocess.run(["ps", "-A", "-o", "pgid=,rss="], capture_output=True, text=True, timeout=10).stdout
        for row in listing.splitlines():
            parts = row.split()
            if len(parts) == 2 and parts[0] == str(pgid):
                kib += int(parts[1])
    except (OSError, ValueError, subprocess.SubprocessError):
        return 0.0
    return kib / 1024


class _Ceiling:
    """`with _Ceiling(proc):` around the wait for a program started with `start_new_session=True`: stops its whole
    process group if the group's memory passes `_CHILD_MIB`, and on the way out (an exception, a time limit
    arriving, or a normal end) leaves nothing of the group running. Afterwards `.check(name)` raises the
    AssertionError that says why, if the ceiling is what stopped it."""

    def __init__(self, proc):
        self.proc, self.over, self._done = proc, [], threading.Event()
        self._thread = threading.Thread(target=self._watch, daemon=True)

    def kill(self):
        try:
            if hasattr(os, "killpg"):
                os.killpg(self.proc.pid, signal.SIGKILL)
            else:                                            # Windows: no process groups, so the program alone
                self.proc.kill()
        except OSError:
            pass

    def _watch(self):
        while not self._done.wait(0.05):
            used = _group_mib(self.proc.pid)
            if used > _CHILD_MIB:
                self.over.append(used)
                self.kill()
                return

    def __enter__(self):
        self._thread.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self._done.set()
        self._thread.join(2)
        self.kill()
        if exc_type is not None:
            self.proc.wait()
        return False

    def check(self, name: str) -> None:
        if self.over:
            raise AssertionError(f"{os.path.basename(str(name))} was stopped after it used over {_CHILD_MIB} MiB of memory "
                                 f"(it had reached {self.over[0]:.0f} MiB): a loop in your C code that keeps allocating or "
                                 "appending never stops; give every loop a cap")
        if getattr(self, "printed", 0) > _CHILD_OUTPUT_MIB * 2**20:
            raise AssertionError(f"{os.path.basename(str(name))} was stopped after it printed over {_CHILD_OUTPUT_MIB} MiB: a loop "
                                 "in your C code that prints on every turn never stops; give every loop a cap")


def _run_child(cmd, *, cwd=None, env=None, input=None, stdin=None, timeout=None):
    """`subprocess.run(cmd, capture_output=True, text=True, ...)` for a program that runs the student's code, under
    the memory ceiling above and a bound on what it prints: an AssertionError that says so if it passes either,
    `subprocess.TimeoutExpired` if `timeout` passes (as subprocess.run raises it), and nothing left running in its
    group whatever happens. Returns a CompletedProcess."""
    if not (hasattr(os, "killpg") and hasattr(signal, "SIGKILL")):          # Windows: no process groups, no ceiling
        return subprocess.run(cmd, capture_output=True, text=True, cwd=cwd, env=env, timeout=timeout,
                              **({"input": input} if input is not None else {"stdin": stdin}))
    proc = subprocess.Popen(cmd, cwd=cwd, env=env, stdin=subprocess.PIPE if input is not None else stdin,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
    chunks, printed = ([], []), [0]

    def read(pipe, into):
        for block in iter(lambda: pipe.read1(65536), b""):
            into.append(block)
            printed[0] += len(block)
            if printed[0] > _CHILD_OUTPUT_MIB * 2**20:
                ceiling.printed = printed[0]
                ceiling.kill()
                break

    with _Ceiling(proc) as ceiling:
        readers = [threading.Thread(target=read, args=(proc.stdout, chunks[0]), daemon=True),
                   threading.Thread(target=read, args=(proc.stderr, chunks[1]), daemon=True)]
        for r in readers:
            r.start()
        if input is not None:
            try:
                proc.stdin.write(input.encode())
                proc.stdin.close()
            except BrokenPipeError:
                pass
        try:
            proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            raise subprocess.TimeoutExpired(cmd, timeout) from None
        for r in readers:
            r.join(5)
    ceiling.check(cmd[0])
    import locale
    out, err = (b"".join(c).decode(locale.getpreferredencoding(False), "replace").replace("\r\n", "\n").replace("\r", "\n")
                for c in chunks)
    return subprocess.CompletedProcess(cmd, proc.returncode, out, err)
# --- END COMMONS CHILD LIMIT ---

_CHILD_TIMEOUT = 55
_CMD_SECONDS = 6       # one command of the binary does a few thousand cases in well under a second


def parse_report(text: str) -> dict:
    """Parse the `@ key=value` lines the binary prints."""
    rep = {}
    for line in text.splitlines():
        if line.startswith("@ "):
            key, value = line[2:].split("=", 1)
            rep[key] = int(value)
    return rep


def run_cmd(command: str, cases: list) -> list:
    """Send one case per line to one command of the binary and return its answer lines, split into tokens.
    The binary prints exactly one line per case; anything else is a bug in a function that prints."""
    text = "\n".join(cases) + "\n"
    try:
        proc = _run_child([_binary(), command], cwd=LESSON_DIR, input=text, timeout=_CMD_SECONDS)
    except subprocess.TimeoutExpired:
        raise AssertionError(f"{BIN} {command} did not finish in {_CMD_SECONDS} s: a function in lesson.cpp never returns "
                             "(a loop whose stopping condition is never met); give every loop a cap") from None
    _raise_for(proc.returncode, command, proc.stderr)
    lines = [ln.split() for ln in proc.stdout.splitlines()]
    assert len(lines) == len(cases), (f"{command}: {len(cases)} cases went in and {len(lines)} answer lines came "
                                      "back. A function must not print: the harness does the printing")
    return lines


def hx(v) -> str:
    """The 8 hex digits of a float32's bits: the way numbers cross the pipe, so nothing is rounded in text."""
    return f"{np.asarray(v, dtype=f32).view(np.uint32).item():08x}"


def unhx(token: str) -> np.float32:
    return np.uint32(int(token, 16)).view(f32)


def bits32(a) -> np.ndarray:
    return np.ascontiguousarray(np.asarray(a, dtype=f32)).view(np.uint32)


def same_bits(a, b) -> np.ndarray:
    """Elementwise: identical float32 bit patterns, or both NaN (every NaN pattern counts as one NaN)."""
    a, b = np.asarray(a, dtype=f32), np.asarray(b, dtype=f32)
    return (bits32(a) == bits32(b)) | (np.isnan(a) & np.isnan(b))


def make_test():
    """Run the C++ self-test, what `make test` runs. Returns (exit code, combined output). It is the same for the
    same saved source, so it is run once per saved version of lesson.cpp and the answer reused."""
    binary = _binary()
    key = ("selftest", _BUILT_FROM)
    if key not in _CACHE:
        proc = _run_child([binary, "selftest"], cwd=LESSON_DIR, timeout=_CHILD_TIMEOUT)
        _CACHE[key] = (proc.returncode, (proc.stdout + proc.stderr).rstrip())
    return _CACHE[key]


def roundtrip(fmt: str, x: np.ndarray):
    """Store the float32 array `x` in the format `fmt` ("int4", "mxfp4" or "nvfp4") with YOUR encoder, pack it,
    count the bytes, decode from the packed bytes alone. Returns (decoded float32 array, report dict). The
    report counts what the encoder wrote: code_bytes, scale_bytes, tensor_scale_bytes, and the elements stored
    at the format's top code (top_codes) and those of them that came back smaller in magnitude (clipped)."""
    x = np.ascontiguousarray(np.asarray(x, dtype=f32).ravel())
    path_in, path_out = work_dir() / "in.f32", work_dir() / "out.f32"
    x.tofile(path_in)
    try:
        proc = _run_child([_binary(), "roundtrip", "--fmt", fmt, "--in", str(path_in), "--out", str(path_out)],
                          cwd=LESSON_DIR, timeout=3 * _CMD_SECONDS)
    except subprocess.TimeoutExpired:
        raise AssertionError(f"{BIN} roundtrip did not finish in {3 * _CMD_SECONDS} s: a function in lesson.cpp never returns "
                             "(a loop whose stopping condition is never met); give every loop a cap") from None
    _raise_for(proc.returncode, "roundtrip", proc.stderr)
    y = np.fromfile(path_out, dtype=f32)
    return y, parse_report(proc.stdout)


