# A time limit for every check that calls the student's code: a loop that never ends must fail
# its check, not freeze the notebook or the grader (which imports the notebook). Copy this block
# unchanged; change only the three limits below it. Why it is this careful:
#  * Whoever runs the notebook may already have an alarm running (tools/grade.py stops every
#    rubric row after 45 s; a harness may have one whose default action ends the process). This
#    guard saves it, lets whichever deadline comes first win (handing the signal to the outer
#    handler when it is the outer's turn) and on the way out re-arms it with the time it had left
#    and its interval. Switching it off instead would let the NEXT hang run for ever.
#  * Its own alarm is one-shot, re-armed by hand every 0.25 s once the time is up (in case a bare
#    `except:` swallows the first). A second alarm alone is not enough: `while True: try: ...
#    except: pass` is interrupted inside the `try` every time and carries on. So from the second
#    stop on, a line tracer (sys.settrace, on the running frames too) raises the stop again at the
#    first line the code runs afterwards, which is in the handler, outside the `try`; it is put
#    back as it was on the way out. A repeating alarm kept firing while a runaway loop's huge list
#    was being torn down; a repeat that arrived after the default handler was back ended the
#    process (exit -14, a dead Jupyter kernel), and one that arrived inside contextlib's exit
#    escaped as a raw timeout and left this handler installed.
#    On Python 3.12+ that tracer is sys.monitoring, which stays on after it raises, so a loop
#    inside TWO bare `except:` blocks is stopped as well: the Nth stop lets it raise N-1 times in
#    a row (one per handler it has to leave), and no more, so the `finally:` blocks and context
#    managers that run as the stop travels out are not interrupted again. On 3.11 sys.settrace is
#    unset by the interpreter each time it raises, so only the innermost one is peeled per alarm.
#  * It also watches memory: it compares the process's resident memory with what it was when the
#    block started, and stops the block as soon as the growth passes `memory_mib`. After a memory
#    stop it looks every 5 ms and stops again at once only if the memory is still growing (a bare
#    `except:` swallowed the stop; clean-up that itself allocates over 32 MiB looks the same);
#    otherwise the stop repeats after 0.25 s, as a time stop does, so `finally:` blocks and
#    context managers can clean up. It looks after 0.01 s,
#    then every 0.02 s, and more often (down to every 2 ms) once the growth passes a quarter of
#    the limit or is fast enough to get there soon: numpy can add a gigabyte in a tenth of a
#    second. A loop that appends to a list reaches gigabytes in seconds, long before
#    any sensible time limit, so the time limit alone does not bound it. The limit is 768 MiB:
#    mybinder.org gives a whole notebook 2 GB, the heaviest lesson holds about 800 MiB before a
#    check starts, and a runaway check runs twice in "Run all" (its cell, then the board). The
#    largest growth a correct answer needs in any lesson is 512 MiB. (Resident memory NOW, not the peak so
#    far: a peak only ever rises, so after one runaway check the next would be allowed another
#    `memory_mib` on top of it, and five looping exercises would reach ten gigabytes. Where the
#    system will not say, /proc on Linux and libproc on macOS being the two that do, it falls
#    back to the peak.)
#  * It never raises inside its own set-up, exit or clean-up (nor inside another guard's: guards
#    nest, the grader's wraps this one), and on the way out it takes any alarm of its own that has
#    gone off but not yet been handled (with SIGALRM blocked) before the old handler is put back.
# tools/verify_all.py fails a lesson whose guard does less.
class _OutOfTime(BaseException):
    """Raised inside the guarded block when its time is up. A BaseException, so `except
    Exception:` in the code under test cannot swallow it; it repeats every 0.25 s, and from the
    second time on a line tracer raises it again at the next line the code runs (inside the
    handler that swallowed the first), in case a bare `except:` does. `_time_limit` turns it into
    an AssertionError once it has left that code."""


def _resident() -> float:
    """This process's resident memory now, in MiB (Linux: /proc; macOS: libproc); its peak so far elsewhere."""
    try:
        if sys.platform.startswith("linux"):
            with open("/proc/self/statm") as f:
                return int(f.read().split()[1]) * os.sysconf("SC_PAGE_SIZE") / 2**20
        if sys.platform == "darwin":
            import ctypes, struct
            info = ctypes.create_string_buffer(96)           # struct proc_taskinfo
            if ctypes.CDLL("/usr/lib/libproc.dylib").proc_pidinfo(os.getpid(), 4, 0, info, 96) == 96:
                return struct.unpack_from("QQ", info.raw)[1] / 2**20     # pti_resident_size
    except Exception:
        pass
    import resource
    return resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / (2**20 if sys.platform == "darwin" else 2**10)


@contextlib.contextmanager
def _time_limit(seconds: float, what: str, memory_mib: float = 0):
    """Fail the block with an AssertionError naming `what` if it runs longer than `seconds`, or
    (when `memory_mib` is set) if the process's resident memory grows by more than that while it runs.
    Uses the operating system's alarm (Linux and macOS, main thread); a no-op elsewhere."""
    if not (all(hasattr(signal, name) for name in ("setitimer", "SIGALRM", "pthread_sigmask", "sigpending", "sigwait"))
            and threading.current_thread() is threading.main_thread()):
        yield
        return
    if getattr(_time_limit, "stopped", False):           # a stopped check's frames keep what they built in a
        _time_limit.stopped = False                      # reference cycle until now: free it, so it is not counted
        gc.collect()                                     # as the growth of this block
    message = (f"{what} was still running after {seconds:g} s: a loop whose stopping condition "
               "is never met runs for ever; give every loop a cap")
    started = time.monotonic()
    used_mib = None
    if memory_mib:
        used_mib = _resident
        base_mib = used_mib()                            # resident memory now; only growth beyond it counts
    previous = signal.getsignal(signal.SIGALRM)
    outer_left, outer_every = signal.getitimer(signal.ITIMER_REAL)   # an alarm already running
    # One alarm at a time, never a repeating one. next: when ours is due; outer: when the alarm we
    # found is due (every: its interval); unseen: an alarm is armed and has not reached _fire yet.
    state = {"next": started + seconds, "outer": started + outer_left if outer_left > 0 else None,
             "every": outer_every, "unseen": False, "fired": False, "done": False, "message": message, "count": 0, "budget": 0,
             "traced": False, "tracer": None, "tool": None, "at": None, "thread": threading.get_ident(),
             "me": sys._getframe(), "owner": None}
    owner = state["me"].f_back
    while owner is not None and owner.f_globals is vars(contextlib):    # contextlib's __enter__
        owner = owner.f_back
    state["owner"], state["at"] = owner, owner.f_lineno   # the frame running the `with`, and its line

    def _arm(now, soonest=0.001):                        # one shot, at whichever deadline is next
        due = [t for t in (state["next"], state["outer"]) if t is not None]
        if used_mib and state["next"] is not None and (not state["fired"] or state.get("memory")):
            due.append(now + state.get("poll", 0.01))    # and look at the memory: first after 0.01 s, then as _fire says
        if due:
            signal.setitimer(signal.ITIMER_REAL, max(min(due) - now, soonest))
            state["unseen"] = True

    def _in_guard(frame):                                # is the alarm landing in a guard's own set-up, exit
        while frame is not None and frame is not state["owner"]:     # or clean-up (this one's or another's:
            code = frame.f_code                          # guards nest), or in contextlib's __exit__ under
            if (frame is state["me"] or code in _own_code or code.co_name in _GUARDS   # a `with`?
                    or frame.f_globals.get("__name__") == "contextlib"):
                return True
            frame = frame.f_back
        return False

    def _fire(signum, frame):
        state["unseen"] = False
        if state["done"]:
            return                                       # a late alarm of ours: already handled
        if _in_guard(frame):                             # never raise inside the guard: it is
            _arm(time.monotonic(), 0.01)                 # finishing; look again shortly
            return
        now = time.monotonic()
        if state["outer"] is not None and now >= state["outer"] - 0.005:
            every = state["every"]                       # the outer alarm is due: act as it would
            state["outer"] = state["outer"] + every * (1 + (now - state["outer"]) // every) if every else None
            try:
                if callable(previous):
                    previous(signum, frame)
                elif previous != signal.SIG_IGN:         # its default action ends the process
                    signal.signal(signal.SIGALRM, signal.SIG_DFL)
                    os.kill(os.getpid(), signal.SIGALRM)
            except BaseException:
                state["next"] = None                     # the outer one is stopping the block
                raise
            finally:
                left, every = signal.getitimer(signal.ITIMER_REAL)
                if left > 0:                             # the outer handler armed its next alarm
                    state["outer"], state["every"] = time.monotonic() + left, every
                _arm(time.monotonic())
            now = time.monotonic()
        grown = used_mib() - base_mib if used_mib and (not state["fired"] or state.get("memory")) else 0
        if used_mib and not state["fired"]:              # close to the limit, or fast enough to come close soon
            rate = (grown - state.get("grown", 0)) / max(now - state.get("seen", started), 0.001)   # MiB a second
            state["grown"], state["seen"] = grown, now
            state["poll"] = (0.02 if grown <= memory_mib / 4 and rate * 0.02 <= (memory_mib - grown) / 4 else   # near: by
                                         max(0.002, min(0.01, (memory_mib - grown) / max(rate, 1.0) / 4)))  # a 1/4 of the time left
        if grown > memory_mib and state["next"] is not None and not state["fired"]:   # out of memory before out of time
            state["message"] = (f"{what} was using over {memory_mib:g} MiB more memory than when it started, "
                                f"after {now - started:.1f} s: a loop that keeps adding to a list or a string "
                                "never stops; give every loop a cap")
            state["next"] = now
            state["memory"], state["at_stop"], state["poll"] = True, grown, 0.005   # then look every 5 ms
        elif state.get("memory") and state["fired"] and grown - state["at_stop"] > 32 and state["next"] is not None:
            state["next"], state["at_stop"] = now, grown        # still growing: a bare `except:` swallowed the stop
        if state["next"] is not None and now >= state["next"] - 0.005:
            swallowed = state["fired"]                   # a second stop: the first did not end the block
            state["fired"] = True
            state["count"] += 1
            state["next"] = now + 0.25                   # again, in case a bare `except:` swallows it
            _arm(now)
            if swallowed:
                state["budget"] = state["count"] - 1     # the tracer raises this many times, then leaves clean-up alone
                _trace_from(frame)
            raise _OutOfTime(state["message"], state)
        _arm(now)

    def _trace(frame, event, arg):                       # raises the stop at the next line of code that
        if state["done"] or _in_guard(frame):            # runs: inside the handler that swallowed the last
            return None                                  # (the interpreter then unsets it; the next alarm
        if event == "line":                              # sets it again)
            raise _OutOfTime(state["message"], state)
        return _trace

    def _line(code, line):                               # Python 3.12+: sys.monitoring, which is not unset
        if state["done"] or state["budget"] <= 0 or threading.get_ident() != state["thread"]:   # not unset when a
            return                                       # callback raises: the next line the code runs raises too, handlers
        frame = sys._getframe(1)                         # included (this thread only), but only `budget` times:
        if _in_guard(frame) or (frame is state["owner"] and line == state["at"]):   # clean-up that runs once the stop has
            return                                       # left the swallowing loops must not be interrupted again
        state["budget"] -= 1                             # (not the `with` line: its exit runs the guard)
        raise _OutOfTime(state["message"], state)

    def _trace_from(frame):                              # trace the running frames, and the ones called next
        if not state["traced"]:
            state["traced"] = True
            mon = getattr(sys, "monitoring", None)
            for tool in (5, 4, 3, 2, 1, 0) if mon is not None else ():
                try:
                    mon.use_tool_id(tool, "commons-time-limit")
                except ValueError:                       # a debugger or a profiler has this one
                    continue
                state["tool"] = tool
                mon.register_callback(tool, mon.events.LINE, _line)
                mon.set_events(tool, mon.events.LINE)
                return
            state["tracer"] = sys.gettrace()
            sys.settrace(_trace)
        while frame is not None and frame is not state["owner"]:
            frame.f_trace = _trace
            frame = frame.f_back

    _GUARDS = ("_time_limit", "_deadline", "_resident", "_fire", "_arm", "_trace", "_trace_from", "_line", "_in_guard")
    _own_code = (_fire.__code__, _arm.__code__, _trace.__code__, _trace_from.__code__, _line.__code__)
    signal.signal(signal.SIGALRM, _fire)
    _arm(time.monotonic())
    try:
        try:
            yield
        finally:
            state["done"] = True                         # from here on an alarm of ours only counts
            if state["traced"]:
                state["traced"] = False
                if state["tool"] is not None:
                    sys.monitoring.set_events(state["tool"], 0)
                    sys.monitoring.register_callback(state["tool"], sys.monitoring.events.LINE, None)
                    sys.monitoring.free_tool_id(state["tool"])
                else:
                    sys.settrace(state["tracer"])        # the tracer that was there before, if any
            mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGALRM})
            try:
                if signal.setitimer(signal.ITIMER_REAL, 0)[0] == 0 and state["unseen"]:
                    # Ours went off and has not reached _fire: it is pending here, or on its way to
                    # another thread. Take it before the old handler (by default, one that ends the
                    # process) is back.
                    give_up = time.monotonic() + 0.5
                    while state["unseen"] and time.monotonic() < give_up:
                        if signal.SIGALRM in signal.sigpending():
                            signal.sigwait({signal.SIGALRM})
                            state["unseen"] = False
                        else:
                            time.sleep(0.001)            # another thread has it: _fire runs next
                signal.signal(signal.SIGALRM, signal.SIG_DFL if previous is None else previous)
                outer = state["outer"]                   # re-arm the alarm we found, last
                signal.setitimer(signal.ITIMER_REAL, *((max(outer - time.monotonic(), 0.001), state["every"])
                                                       if outer is not None else (0, 0)))
            finally:
                signal.pthread_sigmask(signal.SIG_SETMASK, mask)
                state["me"] = state["owner"] = None
    except _OutOfTime as exc:
        if exc.args[-1] is not state:                    # an enclosing guard's: not ours to report
            raise
        _time_limit.stopped = True
        raise AssertionError(state["message"]) from None
    if state["fired"]:                                   # the block caught our alarm and carried on
        _time_limit.stopped = True
        raise AssertionError(state["message"])


# The three limits. A correct answer needs a small fraction of the first two (at least five times
# less, measured on the worked solution, on the slower of a Mac and an emulated Linux machine), so
# only a loop that never stops, or one that keeps appending until memory runs out, ever meets one.
_CHECK_SECONDS = 10     # an exercise's check
_DEMO_SECONDS = 60     # any other cell that runs your code: a demo, a table, a figure
_MEMORY_MIB = 768      # how far a check may grow the process's resident memory before it is stopped


def _limited(label: str, check):
    """Run `check()` under `_time_limit` and return what it returns: _CHECK_SECONDS for an
    exercise's check, _DEMO_SECONDS for anything else. A check that is stopped (too long, or too
    much memory) fails with an AssertionError that says so; whatever the stopped code had built (a
    runaway list can hold gigabytes) is freed at once, not whenever the garbage collector next
    runs; and every program it had started that is still running is stopped too."""
    seconds = _CHECK_SECONDS if label.lower().startswith("exercise") else _DEMO_SECONDS
    before = _processes()
    try:
        with _time_limit(seconds, "this check", _MEMORY_MIB):
            return check()
    except AssertionError as exc:
        if not str(exc).startswith("this check was "):
            raise                                        # the check's own verdict, unchanged
        message = str(exc)
    gc.collect()          # the stopped frames hold what they built in a reference cycle until now
    _stop_strays(before)
    raise AssertionError(message)


def _processes() -> dict:
    """{pid: (parent, process group)} of every process (Linux: /proc; macOS: ps); {} if unreadable."""
    table = {}
    try:
        if os.path.isdir("/proc/self"):
            for entry in os.listdir("/proc"):
                if entry.isdigit():
                    try:
                        with open(f"/proc/{entry}/stat") as f:
                            fields = f.read().rsplit(")", 1)[1].split()
                        table[int(entry)] = (int(fields[1]), int(fields[2]))
                    except (OSError, ValueError, IndexError):
                        continue
        else:
            listing = subprocess.run(["ps", "-A", "-o", "pid=,ppid=,pgid="], capture_output=True, text=True,
                                     timeout=10).stdout
            for row in listing.splitlines():
                pid, ppid, pgid = (int(x) for x in row.split())
                table[pid] = (ppid, pgid)
    except (OSError, ValueError, subprocess.SubprocessError):
        return {}
    return table


def _stop_strays(before: dict) -> None:
    """Stopping a check stops the program it was waiting for, but not what THAT program started:
    stop `make test` and the test binary make launched runs on, at full speed, for ever. Stop every
    process that did not exist before the check (`before`, from _processes()) and either descends
    from this one or sits in its process group (an orphan: its parent is gone, so it now belongs to
    pid 1 or to a subreaper, whichever this machine has). Nothing that was already running is
    touched, the launcher that started this notebook included. Best effort."""
    now, me, group = _processes(), os.getpid(), os.getpgrp()
    if not before or not now:
        return
    def descends(pid):
        seen = set()
        while pid in now and pid not in seen:
            seen.add(pid)
            pid = now[pid][0]
            if pid == me:
                return True
        return False
    for pid, (_, pgid) in now.items():
        if pid != me and pid not in before and (pgid == group or descends(pid)):
            try:
                os.kill(pid, signal.SIGKILL)
            except OSError:
                pass
# --- END COMMONS TIME LIMIT ---

def _try(label: str, check: Callable[[], None], needs: tuple[str, ...] = ()) -> None:
    """Run a check, or a demo that depends on your code, without derailing the notebook.

    A stub you have not filled in yet simply says so. A wrong answer prints the check's own
    message, which names the likely mistake, and the notebook carries on, so one broken
    exercise never hides the feedback on the others. A demo names the exercises it `needs`:
    until each has passed its check, the demo says which one it is waiting for and skips.
    Nothing is swallowed: every outcome is recorded in `_STATUS` for the progress board at the
    foot of the notebook, and every failure in `_FAILED_CHECKS`, which ends a script run
    non-zero.
    """
    waiting = [name for name in _EXERCISES   # in the order you meet them
               if name in needs and _STATUS.get(name) != "passed"]
    if waiting:
        _STATUS[label] = "not started"
        print(f"{label}: skipped - needs {_named(waiting)} to pass first.")
        return
    try:
        _limited(label, check)
    except NotImplementedError as exc:
        _STATUS[label] = "not started"
        stub = _stub_of(exc)
        owner = [name for name, funcs in _EXERCISES.items() if stub in funcs and name != label]
        where = "in lesson.cpp" if stub in _IN_CPP else "above"
        if owner:
            print(f"{label}: skipped - needs {_named(owner)} first.")
        elif label in _EXERCISES:
            print(f"{label}: not implemented yet - fill in {stub}() {where}, then re-run "
                  "this cell.")
        elif any(stub in funcs for funcs in _EXERCISES.values()):
            print(f"{label}: skipped - {stub}() is not implemented yet.")
        else:
            print(f"{label}: not started - {exc}")
    except AssertionError as exc:
        _STATUS[label] = "failed"
        _FAILED_CHECKS.append(label)
        print(f"{label}: FAILED - {exc}")
    except Exception as exc:  # a half-finished implementation raising something else
        _STATUS[label] = "failed"
        _FAILED_CHECKS.append(label)
        print(f"{label}: raised {type(exc).__name__}: {exc}")
    else:
        _STATUS[label] = "passed"


def _ready(demo: str, *keys: str) -> bool:
    """True when the cells that fill `S[key]` have finished; otherwise say the demo is skipped."""
    missing = [k for k in keys if k not in S]
    if not missing:
        return True
    print(f"{demo}: skipped - it needs the output of an earlier cell that did not finish ({', '.join(missing)}).")
    return False


if _IS_MAIN:
    build()

# %% [markdown]
# ## 1. What a 4-bit format has to solve
#
# A trained weight is a 32-bit float. Storing it in 4 bits leaves 16 patterns, so a format must say
# which 16 numbers they mean. Two designs recur, and this lesson builds both.
#
# - **Integers with a scale.** The 16 patterns are the integers -8 to 7 (INT4); one float `scale`
#   shared by a block of weights turns an integer `q` into the weight `q * scale`. The 16 values are
#   evenly spaced, so a block with a few big weights spends its whole grid on the big ones.
# - **A tiny float.** E2M1 spends the 4 bits as 1 sign bit, 2 exponent bits and 1 mantissa bit. Its
#   magnitudes are 0, 0.5, 1, 1.5, 2, 3, 4 and 6: dense near zero, sparse near the top. A scale per
#   block still moves the block into that range.
#
# The scale is not free. A block of 32 weights with a 32-bit scale costs `(32 * 4 + 32) / 32 = 5`
# bits per weight, not 4. The **microscaling (MX)** formats of the Open Compute Project cut that cost
# by storing the scale as 8 bits, and NVIDIA's NVFP4 spends a little more on the scale to get it
# closer to what the block needs. The whole lesson is the trade between *bits spent on scales* and
# *error left in the weights*, and every number in it is measured by the code you write.
#
# As of 13 November 2026 the facts the lesson rests on are these (each is in `claims.yaml` with its
# source): the OCP MX v1.0 specification defines MXFP4 as E2M1 elements with a block of 32 and an E8M0
# scale; NVIDIA's NVFP4 definition uses a block of 16, an E4M3 scale and an FP32 per-tensor scale;
# NVIDIA's Blackwell tensor cores implement NVFP4 and AMD's CDNA 4 matrix cores add MXFP4.
#
# First, ask the binary for its contract and check it agrees with this notebook. Nothing below trusts
# a number from a binary built to a different contract.

# %%
def _show_contract() -> None:
    facts = parse_report(_facts_text())
    mirrored = {"int4_block": INT4_BLOCK, "mx_block": MX_BLOCK, "nv_block": NV_BLOCK,
                "e2m1_max": int(E2M1_MAX), "e4m3_max": int(E4M3_MAX)}
    wrong = {k: (facts[k], v) for k, v in mirrored.items() if facts[k] != v}
    assert not wrong, (f"lesson.cpp and this notebook disagree on {wrong} (C++, notebook). Put the "
                       "constants back as they were: every check below assumes them.")
    assert facts["sizeof_float"] == 4 and facts["little_endian"] == 1, (
        "this lesson assumes a 4-byte float and a little-endian machine, and this one disagrees")
    print(f"  INT4 block      {facts['int4_block']} values share one float scale")
    print(f"  MXFP4 block     {facts['mx_block']} values share one E8M0 scale byte")
    print(f"  NVFP4 block     {facts['nv_block']} values share one E4M3 scale byte, plus one float per tensor")
    print(f"  largest values  E2M1 {facts['e2m1_max']}, E4M3 {facts['e4m3_max']}")
    print(f"\n  {DATA_NOTE}")


def _facts_text() -> str:
    proc = _run_child([_binary(), "facts"], cwd=LESSON_DIR, timeout=_CHILD_TIMEOUT)
    _raise_for(proc.returncode, "facts", proc.stderr)
    return proc.stdout


if _IS_MAIN:
    _try("the contract", _show_contract)

# %% [markdown]
# ## 2. The reference, and the weights you will squeeze
#
# Every check in this notebook compares your C++ with a **numpy reference**, given in the next cell. It
# builds the E2M1 and E4M3 value tables from the bit-field formulas, rounds to the nearest value with
# exact halfway handling, and repeats the three formats' arithmetic in float32, operation by operation.
# It is the specification in executable form: your C++ has to match it to the last bit.
#
# The same cell has the **test tensors**: a Gaussian one and a heavy-tailed one (a Student-t with
# three degrees of freedom, built from normal draws), both of standard deviation 0.05. Real weights sit
# between the two, and the heavy tail is what makes a block's largest value much larger than its other
# 31.

# %%
def _field_value_e2m1(c: int) -> float:
    s, e, m = c >> 3, (c >> 1) & 3, c & 1
    mag = 0.5 * m if e == 0 else 2.0 ** (e - 1) * (1 + 0.5 * m)
    return -mag if s else mag


def _field_value_e4m3(b: int) -> float:
    s, e, m = b >> 7, (b >> 3) & 15, b & 7
    if e == 15 and m == 7:
        return math.nan
    mag = 2.0 ** -6 * (m / 8) if e == 0 else 2.0 ** (e - 7) * (1 + m / 8)
    return -mag if s else mag


E2M1_VALUES = np.array([_field_value_e2m1(c) for c in range(16)], dtype=f32)
E2M1_VALUES[8] = f32(-0.0)                                   # code 8 is negative zero
E4M3_VALUES = np.array([_field_value_e4m3(b) for b in range(256)], dtype=f32)
E2M1_MAGS, E4M3_MAGS = E2M1_VALUES[:8], E4M3_VALUES[:127]    # ascending; the index is the code


def _round_to_codes(x, mags) -> np.ndarray:
    """The index (= code) of the nearest of the ascending magnitudes `mags` to |x|; a halfway value goes to the even
    index; anything above the top midpoint (and infinity) lands on the top index."""
    a = np.abs(np.asarray(x, dtype=np.float64))
    mids = (mags[:-1].astype(np.float64) + mags[1:].astype(np.float64)) / 2
    idx = np.searchsorted(mids, a, side="left")
    tie = (idx < len(mids)) & (a == mids[np.minimum(idx, len(mids) - 1)]) & (idx % 2 == 1)
    return np.where(tie, idx + 1, idx)


def ref_e2m1_encode(x) -> np.ndarray:
    """E2M1 code of each float: nearest value, halves to the even code, saturating at 6, sign bit from signbit."""
    x = np.asarray(x, dtype=f32)
    return _round_to_codes(x, E2M1_MAGS) + np.where(np.signbit(x), 8, 0)


def ref_e4m3_encode(x) -> np.ndarray:
    """E4M3 byte of each float: nearest value, halves to the even byte, saturating at 448, NaN as 0x7F."""
    x = np.asarray(x, dtype=f32)
    return np.where(np.isnan(x), 0x7F, _round_to_codes(x, E4M3_MAGS) + np.where(np.signbit(x), 128, 0))


def ref_e8m0_decode(byte) -> np.ndarray:
    b = np.asarray(byte, dtype=np.int64)
    return np.where(b == 255, np.float32(np.nan), np.ldexp(f32(1), np.where(b == 255, 0, b - 127))).astype(f32)


def ref_shared_exponent(block, emax: int) -> int:
    """floor(log2(amax)) - emax, from the exponent field of the float (exact), clamped to [-127, 127]."""
    amax = np.abs(np.asarray(block, dtype=f32)).max()
    if amax == 0:
        return -127
    return max(-127, min(127, int(np.frexp(amax)[1]) - 1 - emax))


def _blocks(x, k: int):
    """x as an (n_blocks, k) float32 array, the last block padded with zeros, and the true length."""
    x = np.asarray(x, dtype=f32).ravel()
    nb = -(-len(x) // k)
    pad = np.zeros(nb * k, dtype=f32)
    pad[:len(x)] = x
    return pad.reshape(nb, k), len(x)


def ref_int4(x):
    """INT4 with a float32 scale per 32. Returns (scales, q as int8, decoded float32)."""
    B, n = _blocks(x, INT4_BLOCK)
    amax = np.abs(B).max(axis=1)
    scale = np.where(amax == 0, f32(1), amax / f32(7)).astype(f32)
    q = np.rint(B / scale[:, None]).astype(np.int8)
    q[amax == 0] = 0
    deq = (q.astype(f32) * scale[:, None]).astype(f32)
    return scale, q.ravel()[:n], deq.ravel()[:n]


def ref_mxfp4(x):
    """MXFP4: an E8M0 scale per 32. Returns (scale bytes, codes, decoded float32)."""
    B, n = _blocks(x, MX_BLOCK)
    exps = np.array([ref_shared_exponent(b, 2) for b in B])
    scale = np.ldexp(f32(1), exps).astype(f32)
    codes = ref_e2m1_encode(B / scale[:, None])
    deq = (E2M1_VALUES[codes] * scale[:, None]).astype(f32)
    return (exps + 127).astype(np.int64), codes.ravel()[:n], deq.ravel()[:n]


def ref_nvfp4(x):
    """NVFP4: an E4M3 scale per 16 and one float per tensor. Returns (s_dec, scale bytes, codes, decoded float32)."""
    x = np.asarray(x, dtype=f32).ravel()
    B, n = _blocks(x, NV_BLOCK)
    amax_x = np.abs(x).max()
    s_enc = f32(2688) / amax_x if amax_x > 0 else f32(1)
    s_dec = f32(1) / s_enc
    s_dec_b = np.abs(B).max(axis=1) / f32(6)
    sbytes = ref_e4m3_encode(s_dec_b * s_enc)
    sb = E4M3_VALUES[sbytes]
    with np.errstate(divide="ignore", invalid="ignore"):
        s_enc_b = f32(1) / (sb * s_dec)
        codes = ref_e2m1_encode(B * s_enc_b[:, None])
    codes = np.where((sb == 0)[:, None], 0, codes)
    deq = ((E2M1_VALUES[codes] * sb[:, None]) * s_dec).astype(f32)
    return s_dec, sbytes.astype(np.int64), codes.ravel()[:n], deq.ravel()[:n]


def gaussian_tensor(n: int = N_TENSOR) -> np.ndarray:
    """Seeded Gaussian weights, standard deviation WEIGHT_STD, as float32."""
    return (np.random.default_rng(SEED).normal(0.0, WEIGHT_STD, n)).astype(f32)


def heavy_tensor(n: int = N_TENSOR) -> np.ndarray:
    """Seeded heavy-tailed weights: a Student-t with 3 degrees of freedom, scaled to the same standard deviation,
    built from normal draws only (z0 / sqrt((z1^2 + z2^2 + z3^2) / 3))."""
    z = np.random.default_rng(SEED + 1).normal(size=(n, 4))
    t = z[:, 0] / np.sqrt((z[:, 1:] ** 2).sum(axis=1) / 3.0)
    return (t * WEIGHT_STD / math.sqrt(3.0)).astype(f32)


def _show_reference() -> None:
    print("E2M1 magnitudes by code 0..7 :", " ".join(f"{float(v):g}" for v in E2M1_MAGS))
    print("E4M3: finite magnitudes      :", len(E4M3_MAGS), "(the smallest", f"{float(E4M3_MAGS[1]):.6g}, the largest {float(E4M3_MAGS[-1]):g})")
    for name, t in (("Gaussian", gaussian_tensor()), ("heavy-tailed", heavy_tensor())):
        blocks, _ = _blocks(t, 32)
        ratio = np.abs(blocks).max(axis=1) / np.median(np.abs(blocks), axis=1)
        print(f"{name:13s} {len(t):,} weights, std {float(t.std()):.4f}, largest |w| {float(np.abs(t).max()):.3f}, "
              f"median over blocks of (largest / median |w|) {float(np.median(ratio)):.1f}")


if _IS_MAIN:
    _try("the reference", _show_reference)

# %% [markdown]
# The weights the lesson squeezes come from a small language model. It is the character-level model of
# `T03-L03`, carried over so this notebook stands alone, with an MLP sub-layer added and a width of 64:
# embeddings, one causal attention head and a two-layer ReLU MLP, trained for 1,200 Adam steps on an
# excerpt of Shakespeare's Sonnets (public domain, see `claims.yaml`). Six matrices are quantised: the
# query, key, value and output projections (`Wq`, `Wk`, `Wv`, `Wo`) and the two MLP matrices (`Wf1`,
# `Wf2`). Embeddings, biases and the output head stay in float, which is usual. Each matrix is stored
# as `(inputs, outputs)`; the formats are applied to its transpose, so a block of 16 or 32 runs along
# the **input** dimension, the one a matrix multiplication sums over, as it does in hardware.
#
# The cell after the code trains the model and prints how it did against the unigram baseline.

# %%
CORPUS = """From fairest creatures we desire increase,
That thereby beauty's rose might never die,
But as the riper should by time decease,
His tender heir might bear his memory:
But thou, contracted to thine own bright eyes,
Feed'st thy light's flame with self-substantial fuel,
Making a famine where abundance lies,
Thyself thy foe, to thy sweet self too cruel:
Thou that art now the world's fresh ornament,
And only herald to the gaudy spring,
Within thine own bud buriest thy content,
And tender churl mak'st waste in niggarding:
    Pity the world, or else this glutton be,
    To eat the world's due, by the grave and thee.

II

When forty winters shall besiege thy brow,
And dig deep trenches in thy beauty's field,
Thy youth's proud livery so gazed on now,
Will be a tatter'd weed of small worth held:
Then being asked, where all thy beauty lies,
Where all the treasure of thy lusty days;
To say, within thine own deep sunken eyes,
Were an all-eating shame, and thriftless praise.
How much more praise deserv'd thy beauty's use,
If thou couldst answer 'This fair child of mine
Shall sum my count, and make my old excuse,'
Proving his beauty by succession thine!
    This were to be new made when thou art old,
    And see thy blood warm when thou feel'st it cold.

III

Look in thy glass and tell the face thou viewest
Now is the time that face should form another;
Whose fresh repair if now thou not renewest,
Thou dost beguile the world, unbless some mother.
For where is she so fair whose unear'd womb
Disdains the tillage of thy husbandry?
Or who is he so fond will be the tomb,
Of his self-love to stop posterity?
Thou art thy mother's glass and she in thee
Calls back the lovely April of her prime;
So thou through windows of thine age shalt see,
Despite of wrinkles this thy golden time.
    But if thou live, remember'd not to be,
    Die single and thine image dies with thee.

IV

Unthrifty loveliness, why dost thou spend
Upon thyself thy beauty's legacy?
Nature's bequest gives nothing, but doth lend,
And being frank she lends to those are free:
Then, beauteous niggard, why dost thou abuse
The bounteous largess given thee to give?
Profitless usurer, why dost thou use
So great a sum of sums, yet canst not live?
For having traffic with thyself alone,
Thou of thyself thy sweet self dost deceive:
Then how when nature calls thee to be gone,
What acceptable audit canst thou leave?
    Thy unused beauty must be tombed with thee,
    Which, used, lives th' executor to be.

V

Those hours, that with gentle work did frame
The lovely gaze where every eye doth dwell,
Will play the tyrants to the very same
And that unfair which fairly doth excel;
For never-resting time leads summer on
To hideous winter, and confounds him there;
Sap checked with frost, and lusty leaves quite gone,
Beauty o'er-snowed and bareness every where:
Then were not summer's distillation left,
A liquid prisoner pent in walls of glass,
Beauty's effect with beauty were bereft,
Nor it, nor no remembrance what it was:
    But flowers distill'd, though they with winter meet,
    Leese but their show; their substance still lives sweet.


VI

Then let not winter's ragged hand deface,
In thee thy summer, ere thou be distill'd:
Make sweet some vial; treasure thou some place
With beauty's treasure ere it be self-kill'd.
That use is not forbidden usury,
Which happies those that pay the willing loan;
That's for thyself to breed another thee,
Or ten times happier, be it ten for one;
Ten times thyself were happier than thou art,
If ten of thine ten times refigur'd thee:
Then what could death do if thou shouldst depart,
Leaving thee living in posterity?
    Be not self-will'd, for thou art much too fair
    To be death's conquest and make worms thine heir.

VII

Lo! in the orient when the gracious light
Lifts up his burning head, each under eye
Doth homage to his new-appearing sight,
Serving with looks his sacred majesty;
And having climb'd the steep-up heavenly hill,
Resembling strong youth in his middle age,
Yet mortal looks adore his beauty still,
Attending on his golden pilgrimage:
But when from highmost pitch, with weary car,
Like feeble age, he reeleth from the day,
The eyes, 'fore duteous, now converted are
From his low tract, and look another way:
    So thou, thyself outgoing in thy noon:
    Unlook'd, on diest unless thou get a son.

VIII

Music to hear, why hear'st thou music sadly?
Sweets with sweets war not, joy delights in joy:
Why lov'st thou that which thou receiv'st not gladly,
Or else receiv'st with pleasure thine annoy?
If the true concord of well-tuned sounds,
By unions married, do offend thine ear,
They do but sweetly chide thee, who confounds
In singleness the parts that thou shouldst bear.
Mark how one string, sweet husband to another,
Strikes each in each by mutual ordering;
Resembling sire and child and happy mother,
Who, all in one, one pleasing note do sing:
    Whose speechless song being many, seeming one,
    Sings this to thee: 'Thou single wilt prove none.'

IX

Is it for fear to wet a widow's eye,
That thou consum'st thyself in single life?
Ah! if thou issueless shalt hap to die,
The world will wail thee like a makeless wife;
The world will be thy widow and still weep
That thou no form of thee hast left behind,
When every private widow well may keep
By children's eyes, her husband's shape in mind:
Look! what an unthrift in the world doth spend
Shifts but his place, for still the world enjoys it;
But beauty's waste hath in the world an end,
And kept unused the user so destroys it.
    No love toward others in that bosom sits
    That on himself such murd'rous shame commits.

X

For shame! deny that thou bear'st love to any,
Who for thyself art so unprovident.
Grant, if thou wilt, thou art belov'd of many,
But that thou none lov'st is most evident:
For thou art so possess'd with murderous hate,
That 'gainst thyself thou stick'st not to conspire,
Seeking that beauteous roof to ruinate
Which to repair should be thy chief desire.
"""

VOCAB = sorted(set(CORPUS))
VOCAB_SIZE = len(VOCAB)
STOI = {ch: i for i, ch in enumerate(VOCAB)}
DATA = np.array([STOI[ch] for ch in CORPUS], dtype=np.int64)
_SPLIT = int(0.9 * len(DATA))
TRAIN_DATA, VAL_DATA = DATA[:_SPLIT], DATA[_SPLIT:]

D_MODEL, HIDDEN, CONTEXT = 64, 256, 64
INIT_SEED, TRAIN_SEED, TRAIN_STEPS = 1234, 0, 1200
QUANTISED = ("Wq", "Wk", "Wv", "Wo", "Wf1", "Wf2")


def softmax(x: np.ndarray) -> np.ndarray:
    e = np.exp(x - x.max(axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)


def init_params(seed: int = INIT_SEED, scale: float = 0.02) -> dict:
    rng = np.random.default_rng(seed)
    d, h = D_MODEL, HIDDEN
    return {"E": rng.normal(0, scale, (VOCAB_SIZE, d)), "P": rng.normal(0, scale, (CONTEXT, d)),
            "Wq": rng.normal(0, scale, (d, d)), "Wk": rng.normal(0, scale, (d, d)),
            "Wv": rng.normal(0, scale, (d, d)), "Wo": rng.normal(0, scale, (d, d)),
            "Wf1": rng.normal(0, scale, (d, h)), "bf1": np.zeros(h),
            "Wf2": rng.normal(0, scale, (h, d)), "bf2": np.zeros(d),
            "W1": rng.normal(0, scale, (d, VOCAB_SIZE)), "b1": np.zeros(VOCAB_SIZE)}


def model_forward(params: dict, inputs: np.ndarray, targets=None):
    """Whole-sequence forward pass, (B, T) token ids in. Returns (loss, cache); loss is None without targets."""
    b, t = inputs.shape
    x = params["E"][inputs] + params["P"][None, :t]
    q, k, v = x @ params["Wq"], x @ params["Wk"], x @ params["Wv"]
    scores = (q @ k.transpose(0, 2, 1)) / np.sqrt(D_MODEL)
    scores = np.where(np.tril(np.ones((t, t), dtype=bool))[None], scores, -np.inf)
    a = softmax(scores)
    ctx = a @ v
    h1 = x + ctx @ params["Wo"]
    z = h1 @ params["Wf1"] + params["bf1"]
    m = np.maximum(z, 0.0)
    h = h1 + m @ params["Wf2"] + params["bf2"]
    logits = h @ params["W1"] + params["b1"]
    loss = None
    if targets is not None:
        shifted = logits - logits.max(axis=-1, keepdims=True)
        logp = shifted - np.log(np.exp(shifted).sum(axis=-1, keepdims=True))
        loss = float(-np.take_along_axis(logp, targets[..., None], axis=-1).mean())
    return loss, {"inputs": inputs, "targets": targets, "x": x, "q": q, "k": k, "v": v, "a": a,
                  "ctx": ctx, "h1": h1, "z": z, "m": m, "h": h, "logits": logits}


def model_backward(params: dict, cache: dict) -> dict:
    """Gradients of the mean cross-entropy with respect to every parameter."""
    b, t = cache["inputs"].shape
    d, hid = D_MODEL, HIDDEN
    onehot = np.zeros_like(cache["logits"])
    np.put_along_axis(onehot, cache["targets"][..., None], 1.0, axis=-1)
    d_logits = (softmax(cache["logits"]) - onehot) / (b * t)
    grads = {"W1": cache["h"].reshape(-1, d).T @ d_logits.reshape(-1, VOCAB_SIZE),
             "b1": d_logits.sum(axis=(0, 1))}
    d_h = d_logits @ params["W1"].T
    grads["Wf2"] = cache["m"].reshape(-1, hid).T @ d_h.reshape(-1, d)
    grads["bf2"] = d_h.sum(axis=(0, 1))
    d_z = (d_h @ params["Wf2"].T) * (cache["z"] > 0)
    grads["Wf1"] = cache["h1"].reshape(-1, d).T @ d_z.reshape(-1, hid)
    grads["bf1"] = d_z.sum(axis=(0, 1))
    d_h1 = d_h + d_z @ params["Wf1"].T
    grads["Wo"] = cache["ctx"].reshape(-1, d).T @ d_h1.reshape(-1, d)
    d_ctx = d_h1 @ params["Wo"].T
    a, q, k, v, x = cache["a"], cache["q"], cache["k"], cache["v"], cache["x"]
    d_a = d_ctx @ v.transpose(0, 2, 1)
    d_v = a.transpose(0, 2, 1) @ d_ctx
    d_scores = a * (d_a - (d_a * a).sum(axis=-1, keepdims=True)) / np.sqrt(d)
    d_q, d_k = d_scores @ k, d_scores.transpose(0, 2, 1) @ q
    xf = x.reshape(-1, d)
    grads["Wq"], grads["Wk"], grads["Wv"] = (xf.T @ d_q.reshape(-1, d), xf.T @ d_k.reshape(-1, d),
                                             xf.T @ d_v.reshape(-1, d))
    d_x = d_h1 + d_q @ params["Wq"].T + d_k @ params["Wk"].T + d_v @ params["Wv"].T
    grads["P"] = np.zeros_like(params["P"])
    grads["P"][:t] = d_x.sum(axis=0)
    grads["E"] = np.zeros_like(params["E"])
    np.add.at(grads["E"], cache["inputs"], d_x)
    return grads


def train_checkpoint(steps: int = TRAIN_STEPS, lr: float = 3e-3, batch_size: int = 32):
    """Train from INIT_SEED with Adam. Returns (params, [(step, loss)])."""
    params = init_params()
    m = {name: np.zeros_like(p) for name, p in params.items()}
    s = {name: np.zeros_like(p) for name, p in params.items()}
    rng = np.random.default_rng(TRAIN_SEED)
    history = []
    for step in range(1, steps + 1):
        starts = rng.integers(0, len(TRAIN_DATA) - CONTEXT, size=batch_size)
        inputs = np.stack([TRAIN_DATA[i:i + CONTEXT] for i in starts])
        targets = np.stack([TRAIN_DATA[i + 1:i + CONTEXT + 1] for i in starts])
        loss, cache = model_forward(params, inputs, targets)
        grads = model_backward(params, cache)
        for name, p in params.items():
            m[name] = 0.9 * m[name] + 0.1 * grads[name]
            s[name] = 0.999 * s[name] + 0.001 * grads[name] ** 2
            p -= lr * (m[name] / (1 - 0.9 ** step)) / (np.sqrt(s[name] / (1 - 0.999 ** step)) + 1e-8)
        if step == 1 or step % 400 == 0:
            history.append((step, loss))
    return params, history


def windows(data: np.ndarray, length: int = CONTEXT):
    """Consecutive non-overlapping (input, target) windows covering `data`, as two (N, length) arrays."""
    n = (len(data) - 1) // length
    return (np.stack([data[i * length:i * length + length] for i in range(n)]),
            np.stack([data[i * length + 1:i * length + length + 1] for i in range(n)]))


VAL_X, VAL_Y = windows(VAL_DATA)
_counts = np.bincount(TRAIN_DATA, minlength=VOCAB_SIZE).astype(np.float64)
_p = _counts[_counts > 0] / _counts.sum()
UNIGRAM_ENTROPY = float(-(_p * np.log(_p)).sum())
PARAMS: dict = {}


def _train_and_report() -> None:
    params, history = train_checkpoint()
    for step, loss in history:
        print(f"  step {step:5d}  training loss {loss:.3f} nats per character")
    PARAMS.update(params)
    held = model_forward(params, VAL_X, VAL_Y)[0]
    n_q = sum(int(params[n].size) for n in QUANTISED)
    print(f"{len(CORPUS):,} characters, {VOCAB_SIZE} distinct; {n_q:,} weights in the {len(QUANTISED)} matrices that "
          f"will be quantised ({', '.join(f'{n} {params[n].shape[0]}x{params[n].shape[1]}' for n in QUANTISED)})")
    S["model"] = True
    print(f"held-out loss {held:.2f} nats per character against {UNIGRAM_ENTROPY:.2f} for a model that knows only how often "
          f"each character occurs: the model {'beats' if held < UNIGRAM_ENTROPY else 'does not beat'} that baseline on text it never saw")


if _IS_MAIN:
    _try("the model", _train_and_report)


def weight_tensors() -> dict:
    """The six matrices as float32 arrays of shape (outputs, inputs), C-contiguous: what gets quantised."""
    return {n: np.ascontiguousarray(PARAMS[n].T.astype(f32)) for n in QUANTISED}


def with_weights(replacements: dict) -> dict:
    """A copy of the trained parameters with some matrices replaced; each replacement is (outputs, inputs)."""
    out = dict(PARAMS)
    for name, w in replacements.items():
        out[name] = np.asarray(w, dtype=np.float64).T
    return out


def log_probs(params: dict, inputs: np.ndarray) -> np.ndarray:
    logits = model_forward(params, inputs)[1]["logits"]
    shifted = logits - logits.max(axis=-1, keepdims=True)
    return shifted - np.log(np.exp(shifted).sum(axis=-1, keepdims=True))


def evaluate(replacements: dict) -> tuple:
    """(held-out loss in nats per character, KL divergence in nats per position from the model with the same matrices
    held as float32). Both on the held-out windows."""
    params = with_weights(replacements)
    loss = model_forward(params, VAL_X, VAL_Y)[0]
    lp_ref, lp = log_probs(with_weights(weight_tensors()), VAL_X), log_probs(params, VAL_X)
    kl = float(np.mean(np.sum(np.exp(lp_ref) * (lp_ref - lp), axis=-1)))
    return loss, kl

# %% [markdown]
# ## 3. Exercise 1 — nibbles, in `lesson.cpp`
#
# From here the work is in C++. Open `lesson.cpp`; each stub's comment carries the requirements and a
# worked example. Your feedback loop is `make test`, which the cell after the exercise runs: it reports
# each C++ exercise on its own line, TODO until you fill it in. The notebook's checks go further, and
# compare your functions with the numpy reference above on hundreds of cases at a time.
#
# A 4-bit code is a **nibble**. Memory is addressed in bytes, so a 4-bit format has to put two codes in
# one byte, and every size this lesson prints later is counted from bytes that were really packed.
# Four small functions: `pack_nibbles` and `unpack_nibbles` move two nibbles in and out of a byte (the
# first entry in the low half), and `int4_to_nibble` and `nibble_to_int4` turn a signed integer from
# -8 to 7 into its 4-bit two's-complement pattern and back. The count `n` of entries can be anything from 0 to several
# hundred, so no index or buffer may assume a small `n`.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# What is the pattern of -1 in 4 bits, and of -8? Bit 3 is the sign. When you read a pattern back, which
# value of the integer 0 to 15 means a negative number, and what do you subtract to get it? And an entry
# of the input array is a whole `uint8_t`: what do the top four bits hold when only the low four count?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# To pack, mask each entry with 15, shift the second one left by four and combine the two with a bitwise
# or; with an odd count the second entry of the last byte does not exist, so use zero. To unpack, take the
# low four bits of the byte for even entries and the byte shifted right by four for odd ones. To read a
# signed nibble, mask with 15 and subtract 16 when the result is 8 or more.
#
# </details>

# %%
def _need_selftest(exercise: str) -> None:
    """The self-test's line for one exercise, as a check: a failure is an AssertionError carrying the binary's
    own message; a stub is a NotImplementedError naming the function."""
    _code, out = make_test()
    for line in out.splitlines():
        if f"{exercise}  " in line:
            word = line.split()[0]
            if word == "FAIL":
                raise AssertionError("make test says: " + line.strip().replace("FAIL  ", "", 1))
            if word == "TODO":
                raise NotImplementedError(line.split(": ", 1)[1])
            return
    raise AssertionError(f"make test printed no line for {exercise}: {out[-300:]}")


def _need_selftests(*exercises: str) -> None:
    """Exercises that build on others first need those others' self-test lines to pass, so a hang or a wrong answer
    upstream is reported here, in the seconds the self-test takes, and not as a puzzling mismatch."""
    for exercise in exercises:
        _need_selftest(exercise)


def _show_selftest() -> None:
    code, out = make_test()
    print(out)
    print(f"\nexit code {code}  (0 = all pass, 2 = something is still a stub, 1 = a failure)")


def _ints(tokens) -> list:
    return [int(t) for t in tokens]


_PACK_SMALL = list(range(0, 12)) + [31, 32, 33, 64, 65]
_PACK_LARGE = [127, 128, 129, 254, 255, 256, 257, 300]       # a count above 127 or 255 must not overflow an index or a buffer


def _pack_first_bad(sizes: list, seed: int) -> str:
    """The first disagreement of pack_nibbles with the definition on random entries of these sizes, or ''."""
    rng = np.random.default_rng(seed)
    values = [rng.integers(0, 256, n) for n in sizes]
    got = run_cmd("pack", [" ".join(map(str, [n, *v])) for n, v in zip(sizes, values)])
    for n, v, g in zip(sizes, values, got):
        want = [int(v[2 * i] & 15) | (int(v[2 * i + 1] & 15) << 4 if 2 * i + 1 < n else 0) for i in range((n + 1) // 2)] + [0xA5]
        if _ints(g) != want:
            return (f"pack_nibbles on {n} entries {v[:6].tolist()}{' ...' if n > 6 else ''} gave bytes {_ints(g)[:8]}"
                    f"{' ...' if len(g) > 8 else ''}, expected {want[:8]}{' ...' if len(want) > 8 else ''} (the last number is a guard byte just past the end, which must stay 165). "
                    "Entry 2i is the LOW nibble, only the low 4 bits of each entry count, an odd count leaves the last high nibble zero, "
                    "and nothing is written past byte (n + 1) / 2 - 1; the count can be several hundred")
    return ""


def _nib_pack() -> None:
    why = _pack_first_bad(_PACK_SMALL, SEED + 11)
    assert not why, why
    why = _pack_first_bad(_PACK_LARGE, SEED + 111)
    assert not why, why
    got = run_cmd("pack", ["4 255 255 255 255", "3 240 241 0"])
    assert [_ints(g) for g in got] == [[255, 255, 0xA5], [0x10, 0x00, 0xA5]], (
        f"pack_nibbles on entries with junk in their top four bits gave {[_ints(g) for g in got]}: only the low four bits of an entry count, "
        "so {255, 255, 255, 255} packs to 255, 255 and {240, 241, 0} to 0x10 and 0x00")


def _unpack_first_bad(sizes: list, seed: int) -> str:
    rng = np.random.default_rng(seed)
    bytes_in = [rng.integers(0, 256, (n + 1) // 2) for n in sizes]
    got = run_cmd("unpack", [" ".join(map(str, [n, *b])) for n, b in zip(sizes, bytes_in)])
    for n, b, g in zip(sizes, bytes_in, got):
        want = [int(b[i // 2] >> 4) if i % 2 else int(b[i // 2] & 15) for i in range(n)] + [0x55]
        if _ints(g) != want:
            return (f"unpack_nibbles on bytes {b[:4].tolist()}{' ...' if len(b) > 4 else ''} with n = {n} gave {_ints(g)[:8]}{' ...' if len(g) > 8 else ''}, "
                    f"expected {want[:8]}{' ...' if len(want) > 8 else ''} (the last number is a guard just past the last entry, which must stay 85). Entry 2i "
                    "is the low nibble of byte i and entry 2i + 1 the high nibble; write exactly n entries, each 0 to 15; the count can be several hundred")
    return ""


def _nib_unpack() -> None:
    why = _unpack_first_bad(_PACK_SMALL, SEED + 11)
    assert not why, why
    why = _unpack_first_bad(_PACK_LARGE, SEED + 112)
    assert not why, why


def _nib_convert() -> None:
    got = run_cmd("i4n", [str(q) for q in range(-8, 8)])
    assert [int(g[0]) for g in got] == [q & 15 for q in range(-8, 8)], (
        f"int4_to_nibble(-8 .. 7) gave {[int(g[0]) for g in got]}: the 4-bit two's-complement pattern, -1 is 15 and -8 is 8")
    got = run_cmd("n4i", [str(v) for v in range(512)])
    want = [(v & 15) - 16 if (v & 15) >= 8 else (v & 15) for v in range(512)]
    assert [int(g[0]) for g in got] == want, (
        "nibble_to_int4 must look only at the low 4 bits, whatever the argument (mask with 15, so 0xF8 reads as -8 and 0x17 as 7), then subtract 16 "
        "from a pattern of 8 or more")


def _check_nibbles() -> None:
    _need_selftest("exercise 1")
    _nib_pack()
    _nib_unpack()
    _nib_convert()
    print("exercise 1 looks right: pack, unpack and both conversions agree with the reference on every case")


if _IS_MAIN:
    _try("make test", _show_selftest)
    _try("exercise 1", _check_nibbles)

# %% [markdown]
# ## 4. Exercise 2 — INT4 with a float scale, in `lesson.cpp`
#
# The simplest 4-bit format. Take a block of up to 32 weights, find the largest magnitude `amax`, set
# `scale = amax / 7`, and store each weight as the nearest integer to `x / scale`. The largest weight
# lands on 7 or -7 and every other weight on a smaller integer; the scale is kept as a 32-bit float,
# which is what makes INT4 cost 5 bits per weight at this block size. Decoding multiplies back.
#
# The rounding rule is **round half to even** (`nearbyintf`), the rule every format in this lesson uses
# and the one the OCP specification requires: 2.5 goes to 2 and 3.5 to 4. Rounding halves away from zero
# looks equivalent, and is not: it is biased, and it will not match the reference.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# Which function rounds halves to even, and which one does not? What should a block of all zeros give,
# when `amax / 7` would be zero and the next step divides by it? And how many values does the function
# write: look at the guard value the check prints after the last code.
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# Scan the block once for the largest `fabsf`. If it is zero, set every code to zero and return a scale of
# 1. Otherwise divide to get the scale, then for each value divide by the scale, round with `nearbyintf`
# and convert to `int8_t`. Decoding is one multiplication per value, in float.
#
# </details>

# %%
# (amax, x) pairs where x sits within a float32 step of a halfway point between two INT4 codes for that block's scale,
# found by search: for them x / scale and x * (1 / scale) round to different codes. The exercise says "a float division".
INT4_DIVISION_PAIRS = [(1.0, 0.2142857164144516), (1.0, 0.3571428954601288), (1.0, 0.9285715222358704), (0.05000000074505806, 0.03214285895228386), (0.30000001192092896, 0.1071428656578064), (0.30000001192092896, 0.19285716116428375), (0.30000001192092896, 0.23571428656578064), (3.0, 0.2142857313156128), (3.0, 0.6428571343421936), (3.0, 1.071428656578064), (3.0, 1.9285715818405151), (7.699999809265137, 1.649999976158142), (0.8999999761581421, 0.44999995827674866), (2.200000047683716, 0.4714285731315613), (2.200000047683716, 1.7285714149475098), (13.0, 6.499999523162842), (13.0, 10.214284896850586)]


def _int4_hand_blocks() -> list:
    """Halfway values at two scales, an all-zero block (either sign of zero), one value, an outlier."""
    blocks = [[7.0] + [s * (k + 0.5) for k in range(7) for s in (1, -1)],
              [3.5] + [s * 0.5 * (k + 0.5) for k in range(7) for s in (1, -1)],
              [0.0] * 5, [-0.0, 0.0, -0.0], [0.0] * 9 + [1e-3] + [0.0] * 4, [1.0], [-2.5], [1000.0] + [0.3] * 31]
    return [np.asarray(b, dtype=f32) for b in blocks]


def _int4_random_blocks() -> list:
    """Random blocks of every length from 1 to 32, at scales from 1e-6 to 1e3."""
    rng = np.random.default_rng(SEED + 12)
    blocks = [rng.normal(0, 10.0 ** rng.uniform(-6, 3), n).astype(f32) for n in (1, 2, 3, 7, 16, 31, 32) for _ in range(12)]
    return blocks


def _int4_heavy_blocks() -> list:
    return [b.astype(f32) for b in heavy_tensor(32 * 40).reshape(40, 32)]


def _int4_tie_sweep() -> list:
    """With amax = 7 * 2^j the scale is exactly 2^j and (k + 0.5) * scale is an exact halfway value: swept over the
    exponent j, both signs, and the float32 either side of each halfway value."""
    blocks = []
    for j in (-10, -3, 0, 4, 9):
        s = 2.0 ** j
        for k in range(0, 7):
            for sign in (1, -1):
                tie = sign * (k + 0.5) * s
                for x in (tie, float(np.nextafter(f32(tie), f32(0))), float(np.nextafter(f32(tie), f32(1e9 * sign)))):
                    blocks.append(np.array([7 * s, x, -x], dtype=f32))
    return blocks


def _int4_division_blocks() -> list:
    return [np.array(b, dtype=f32) for b in [[a, x] for a, x in INT4_DIVISION_PAIRS] + [[-a, -x] for a, x in INT4_DIVISION_PAIRS]]


def _int4_first_bad(blocks: list) -> str:
    got = run_cmd("int4q", [" ".join([str(len(b))] + [hx(v) for v in b]) for b in blocks])
    for b, g in zip(blocks, got):
        scale, q, _ = ref_int4(b)
        want = [hx(scale[0])] + [str(int(v)) for v in q] + ["99"]
        if g != want:
            shown = b[:4].tolist()
            return (f"int4_quantise_block on {len(b)} values {shown}{' ...' if len(b) > 4 else ''} gave scale bits {g[0]} and codes "
                    f"{g[1:]}, expected scale bits {want[0]} and codes {want[1:]} (the last 99 is a guard past the end). "
                    "scale = amax / 7 in float; the code is nearbyintf(x / scale), a float division and a rounding that sends halves to even "
                    "(not roundf), at every scale; an all-zero block has scale 1 and codes 0; write exactly n codes")
    return ""


def _int4_quantise_part() -> None:
    why = _int4_first_bad(_int4_hand_blocks())
    assert not why, why
    why = _int4_first_bad(_int4_random_blocks())
    assert not why, why
    why = _int4_first_bad(_int4_heavy_blocks())
    assert not why, why
    why = _int4_first_bad(_int4_tie_sweep())
    assert not why, why
    why = _int4_first_bad(_int4_division_blocks())
    assert not why, why


def _int4_dequantise_part() -> None:
    rng = np.random.default_rng(SEED + 13)
    cases, want = [], []
    for n in (1, 5, 32, 32, 32, 17):
        q = rng.integers(-7, 8, n).astype(np.int8)
        scale = f32(10.0 ** rng.uniform(-6, 5))
        cases.append(" ".join([hx(scale), str(n), *map(str, q.tolist())]))
        want.append([hx(v) for v in (q.astype(f32) * scale).astype(f32)] + [hx(f32(12345))])
    for c, g, w in zip(cases, run_cmd("int4dq", cases), want):
        assert g == w, ("int4_dequantise_block must give (float)q[i] * scale for each i < n, one float multiplication each, and write "
                        f"nothing past n; the case {c.split()[:3]} gave something else")


def _check_int4() -> None:
    _need_selftest("exercise 2")
    _int4_quantise_part()
    _int4_dequantise_part()
    print("exercise 2 looks right: scales, codes and decoded values match the reference bit for bit")


if _IS_MAIN:
    _try("exercise 2", _check_int4)


def _show_int4_grid() -> None:
    values = [unhx(t[0]) for t in run_cmd("int4dq", [" ".join([hx(f32(1)), "1", str(q)]) for q in range(8)])]
    print("INT4: the values a block can hold, in units of its scale, and the gap to the next one")
    print(f"  {'q':>3} {'value':>7} {'gap above':>10} {'gap / value':>12}")
    for q in range(1, 8):
        gap = float(values[q + 1] - values[q]) if q < 7 else float("nan")
        print(f"  {q:3d} {float(values[q]):7.1f} {gap:10.1f} {gap / float(values[q]):12.3f}" if q < 7 else
              f"  {q:3d} {float(values[q]):7.1f} {'(top)':>10}")
    print("every gap is the same size: a weight of 1 unit is rounded as coarsely, in absolute terms, as a weight of 6")


if _IS_MAIN:
    _try("the INT4 grid", _show_int4_grid, needs=("exercise 2",))

# %% [markdown]
# ## 5. Exercise 3 — the 4-bit float E2M1, in `lesson.cpp`
#
# E2M1 spends its four bits as `s e e m`: a sign bit, two exponent bits (bias 1) and one mantissa bit.
# An exponent field of zero is **subnormal** and means `0.5 * m`; otherwise the value is
# `2^(e-1) * (1 + m/2)`. That gives the eight magnitudes 0, 0.5, 1, 1.5, 2, 3, 4 and 6, and code 8
# (sign set, everything else zero) is **negative zero**, which compares equal to zero but is a different
# pattern. There is no infinity and no NaN.
#
# Two functions. `e2m1_decode` reads a code from its bit fields. `e2m1_encode` returns the code of the
# nearest value, under three rules, all enforced by the check below. Halfway values round to the code that
# is **even** (`0.75` goes to code 2, the value 1, not to code 1): the OCP specification requires
# round-to-nearest-even. Values of 6 or more **saturate** at code 7 and never wrap round: the specification's
# clamping, which keeps the sign. And the sign bit is the sign of the input even when the magnitude rounds
# to zero, so `-0.1` encodes as code 8: that one is this lesson's rule, so that a decoded tensor keeps every sign.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# The halfway points between the eight magnitudes are 0.25, 0.75, 1.25, 1.75, 2.5, 3.5 and 5. Which
# neighbour has the even code at each one? Is the rule the same at every halfway point, or does it
# alternate? And what does `fabsf` throw away that `std::signbit` keeps?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# For decoding, pull the three fields out with shifts and masks and build the magnitude, then apply
# the sign. For encoding, take the sign from `std::signbit`, work on `fabsf(x)`, return the top code
# at once if it is 6 or more, and otherwise count how many of the seven halfway points the magnitude is
# above, treating a magnitude exactly on a halfway point as above it only when the upper code is even.
#
# </details>

# %%
def _probe_classes(mags: np.ndarray, rng, span: float, log_lo: float, log_hi: float, extra=()) -> dict:
    """Float32 values that stress a rounding grid, in classes (each class is checked on its own line):
    'grid' every halfway value and every magnitude, the float either side of each, both signs;
    'ties' the exact halfway values only, both signs; 'uniform' random values over [-span, span];
    'log' random signed magnitudes spread over 10^log_lo to 10^log_hi; 'special' zeros, infinities, tiny and huge values."""
    mids = (mags[:-1].astype(np.float64) + mags[1:].astype(np.float64)) / 2
    grid, ties = [], []
    for m in list(mids) + list(mags.astype(np.float64)) + [float(v) for v in extra]:
        m = f32(m)
        for v in (m, np.nextafter(m, f32(0)), np.nextafter(m, f32(3e38))):
            grid += [v, -v]
    for m in mids:
        ties += [f32(m), -f32(m)]
    uniform = [f32(v) for v in rng.uniform(-span, span, 2000)]
    log = [f32(v) * f32(rng.choice([-1.0, 1.0])) for v in 10.0 ** rng.uniform(log_lo, log_hi, 1000)]
    special = [f32(0), f32(-0.0), f32(np.inf), f32(-np.inf), f32(1e20), f32(-1e20), f32(1e-20), f32(-1e-20), f32(span), f32(span * 1.0001)]
    return {"grid": np.array(grid, dtype=f32), "ties": np.array(ties, dtype=f32), "uniform": np.array(uniform, dtype=f32),
            "log": np.array(log, dtype=f32), "special": np.array(special, dtype=f32)}


def _e2m1_decode_part() -> None:
    codes = list(range(-3, 300))
    got = run_cmd("e2d", [str(c) for c in codes])
    for c, g in zip(codes, got):
        want = E2M1_VALUES[c & 15]
        assert same_bits(unhx(g[0]), want), (f"e2m1_decode({c}) gave {float(unhx(g[0])):g} (bits {g[0]}), expected {float(want):g} (bits {hx(want)}): "
                                             "sign bit 3, exponent bits 2-1 with bias 1, mantissa bit 0, subnormal when the exponent field is 0; "
                                             "use only the low 4 bits of the argument; code 8 is negative zero")


def _e2m1_first_bad(probes: np.ndarray) -> str:
    got = [int(g[0]) for g in run_cmd("e2e", [hx(p) for p in probes])]
    want = ref_e2m1_encode(probes)
    bad = [i for i in range(len(probes)) if got[i] != want[i]]
    if not bad:
        return ""
    i = bad[0]
    why = ("at a halfway value the EVEN code wins" if abs(float(probes[i])) in (0.25, 0.75, 1.25, 1.75, 2.5, 3.5, 5.0) else
           "saturate at code 7 for 6 and above" if abs(float(probes[i])) >= 6 else
           "keep the sign even when the magnitude rounds to zero" if abs(float(probes[i])) < 0.25 else "the nearest of the eight values")
    return f"e2m1_encode({float(probes[i])!r}) gave code {got[i]}, expected {int(want[i])}: {why}. ({len(bad)} of {len(probes)} probes disagree.)"


def _e2m1_encode_part() -> None:
    probes = _probe_classes(E2M1_MAGS, np.random.default_rng(SEED + 14), 9.0, -20, 20, extra=(6.5, 7.0, 100.0))
    why = _e2m1_first_bad(probes["grid"])
    assert not why, why
    why = _e2m1_first_bad(probes["ties"])
    assert not why, why
    why = _e2m1_first_bad(probes["uniform"])
    assert not why, why
    why = _e2m1_first_bad(probes["log"])
    assert not why, why
    why = _e2m1_first_bad(probes["special"])
    assert not why, why


def _check_e2m1() -> None:
    _need_selftest("exercise 3")
    _e2m1_decode_part()
    _e2m1_encode_part()
    print("exercise 3 looks right: every decode and every halfway, saturating and signed probe agree with the reference")


if _IS_MAIN:
    _try("exercise 3", _check_e2m1)


def _show_e2m1_grid() -> None:
    values = [float(unhx(t[0])) for t in run_cmd("e2d", [str(c) for c in range(8)])]
    print("E2M1: the eight magnitudes, the gap to the next one, and the gap relative to the value")
    print(f"  {'code':>4} {'value':>6} {'gap above':>10} {'gap / value':>12}")
    for c in range(1, 8):
        if c < 7:
            print(f"  {c:4d} {values[c]:6.1f} {values[c + 1] - values[c]:10.1f} {(values[c + 1] - values[c]) / values[c]:12.3f}")
        else:
            print(f"  {c:4d} {values[c]:6.1f} {'(top)':>10}")
    rel = [(values[c + 1] - values[c]) / values[c] for c in range(1, 7)]
    print(f"the relative gap runs from {max(rel):.3f} down to {min(rel):.3f}: a float grid keeps its precision in proportion, an integer grid does not")


if _IS_MAIN:
    _try("the E2M1 grid", _show_e2m1_grid, needs=("exercise 3",))

# %% [markdown]
# ## 6. Exercise 4 — the E8M0 scale and the shared exponent, in `lesson.cpp`
#
# MXFP4 scales a whole block by a **power of two** stored in one byte, **E8M0**: eight exponent bits and
# nothing else, so a byte `b` means `2^(b - 127)` and the byte 255 is the one NaN. `e8m0_decode` is that
# one line. The harder function is `mx_shared_exponent`: the OCP specification's rule is "the largest
# power of two less than or equal to the block's largest magnitude, divided by the largest power of two
# an element can hold". For E2M1 that is 4, so
#
# `X = floor(log2(amax)) - 2`, clamped to the range E8M0 can hold, -127 to 127, and -127 for an all-zero block.
# This function must accept **any finite float**, denormals and the largest floats included.
#
# **The floor must be exact.** `floorf(log2f(a))` looks right and is wrong for a value just below a
# power of two: the float just under 8 is 7.9999995, whose true logarithm is a hair under 3, but
# `log2f` rounds it to exactly 3 and the floor says 3. The exponent is already in the float's bits;
# `ilogbf` (or `frexpf`) reads it exactly. The check feeds the float just below every power of two.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# What is the exponent of 8, and of the float just below 8? Which standard function returns the exponent
# of a float without computing a logarithm? And which blocks need a special answer: all zeros, and values
# so small or so large that `floor(log2) - 2` leaves the range a byte can hold?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# Find the largest `fabsf` in the block. If it is zero return -127. Otherwise take the unbiased exponent
# with `ilogbf`, subtract the element's `emax_elem` argument, and clamp the result into -127 to 127.
# For `e8m0_decode`, mask the argument to a byte, return NaN for 255, and otherwise `ldexpf(1.0f, byte - 127)`.
#
# </details>

# %%
def _shx_power_cases() -> list:
    """Blocks for exercise 4, each as (values, emax_elem): just below, at and above every power of two from 2^-149 (the
    smallest denormal) to 2^127, with the largest value first, last or in the middle."""
    cases = []
    for k in range(-149, 128):
        p = f32(np.ldexp(f32(1), k))
        cases += [([np.nextafter(p, f32(0))], 2), ([p], 2), ([-p, p / 4], 2), ([np.nextafter(p, f32(0)), p / 8], 0),
                  ([p / 8, np.nextafter(p, f32(3e38)), -p / 2], 1), ([p / 4, p / 2, p, -p / 3], 3)]
    return [(np.asarray(v, dtype=f32), emax) for v, emax in cases]


def _shx_random_cases() -> list:
    """Random blocks of 1 to 32 values spread over 60 orders of magnitude, with the largest anywhere in the block."""
    rng = np.random.default_rng(SEED + 15)
    cases = []
    for i in range(300):
        n = int(rng.integers(1, 33))
        mags = 10.0 ** rng.uniform(-30, 30, n)
        cases.append(([f32(m * rng.choice([-1, 1])) for m in mags], int(rng.integers(0, 4))))
    return [(np.asarray(v, dtype=f32), emax) for v, emax in cases]


def _shx_special_cases() -> list:
    cases = [([0.0], 2), ([0.0, -0.0, 0.0], 2), ([1e-45], 2), ([-1e-40], 2), ([3e38], 2), ([3.4028235e38], 3), ([6.0, -3.0], 2), ([6.0], 3)]
    return [(np.asarray(v, dtype=f32), emax) for v, emax in cases]


def _e8m0_part() -> None:
    codes = list(range(-2, 300))
    got = run_cmd("e8d", [str(b) for b in codes])
    want = ref_e8m0_decode(np.array(codes) & 255)
    for b, g, w in zip(codes, got, want):
        assert same_bits(unhx(g[0]), w), (f"e8m0_decode({b}) gave {float(unhx(g[0])):g} (bits {g[0]}), expected {float(w):g}: "
                                                 "2^(b - 127) for 0 to 254, NaN for 255, using only the low 8 bits of the argument")


def _shx_first_bad(cases: list) -> str:
    got = run_cmd("shx", [" ".join([str(len(v)), str(emax), *[hx(x) for x in v]]) for v, emax in cases])
    for (v, emax), g in zip(cases, got):
        want = ref_shared_exponent(v, emax)
        if int(g[0]) != want:
            amax = float(np.abs(v).max())
            return (f"mx_shared_exponent({v[:3].tolist()}{' ...' if len(v) > 3 else ''}, n = {len(v)}, emax_elem = {emax}) gave {int(g[0])}, "
                    f"expected {want} (the largest magnitude is {amax!r}). The floor of the base-2 logarithm must be EXACT: read the "
                    "exponent field with ilogbf, not floorf(log2f(x)), which rounds up just below a power of two; "
                    "subtract emax_elem; clamp to [-127, 127]; an all-zero block gives -127")
    return ""


def _shared_exponent_part() -> None:
    why = _shx_first_bad(_shx_power_cases())
    assert not why, why
    why = _shx_first_bad(_shx_random_cases())
    assert not why, why
    why = _shx_first_bad(_shx_special_cases())
    assert not why, why


def _check_shared_exponent() -> None:
    _need_selftest("exercise 4")
    _e8m0_part()
    _shared_exponent_part()
    print("exercise 4 looks right: every scale byte decodes correctly and every exponent, including the float just below each power of two, matches")


if _IS_MAIN:
    _try("exercise 4", _check_shared_exponent)


def _show_clip_region() -> None:
    """Where MXFP4's floor rule clips: the block's largest value divided by its scale lies in [4, 8), and E2M1 stops at 6."""
    rows = []
    for name, t in (("Gaussian", gaussian_tensor()), ("heavy-tailed", heavy_tensor())):
        B, _ = _blocks(t, MX_BLOCK)
        got = run_cmd("shx", [" ".join([str(MX_BLOCK), "2", *[hx(x) for x in b]]) for b in B])
        exps = np.array([int(g[0]) for g in got])
        ratio = np.abs(B).max(axis=1).astype(np.float64) / np.ldexp(1.0, exps)
        by_mantissa = np.frexp(np.abs(B).max(axis=1))[0] * 2 > 1.5     # mantissa of the largest value above 1.5, i.e. ratio above 6
        assert ((ratio > 6) == by_mantissa).all(), "the ratio test and the mantissa test must agree"
        rows.append((name, len(B), float(ratio.min()), float(ratio.max()), float((ratio > 6).mean())))
    print(f"each block's largest value divided by its scale, and the share of blocks where that is above E2M1's maximum of {E2M1_MAX:g}:")
    for name, nb, lo, hi, share in rows:
        print(f"  {name:13s} {nb:5d} blocks   ratio from {lo:.3f} to {hi:.3f}   above 6 in {100 * share:.1f}% of blocks")
    print("a ratio of 4 to 8 is guaranteed by the rule itself; the part above 6 cannot be stored, so the block's largest value is clipped")


if _IS_MAIN:
    _try("the clip region", _show_clip_region, needs=("exercise 4",))

# %% [markdown]
# ## 7. Exercise 5 — an MXFP4 block, in `lesson.cpp`
#
# Now put the pieces together. An MXFP4 block is up to 32 weights stored as **one E8M0 scale byte** and one
# E2M1 code per weight. To encode: find the shared exponent `X` (exercise 4), store the byte `X + 127`,
# decode that byte to the float `2^X`, divide every weight by it and encode the result as E2M1 (exercise
# 3), which saturates anything above 6. To decode, multiply each element's E2M1 value by the scale. The
# specification says a NaN scale makes every element NaN, and your decoder must do that too: byte 255.
#
# This is the format of the OCP MX v1.0 specification, which fixes the block at 32, the scale as E8M0 and
# the element as E2M1, and leaves the byte layout of the block to the implementer. Dividing by a power of
# two is exact in float, so the only rounding in this format is the E2M1 rounding and the clip. Like
# `mx_shared_exponent`, the block functions must accept **any finite float**.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# Two of the three steps already exist as functions. What is the scale byte for a shared exponent of
# -3? And what happens to a value of 7.5 when the scale is 1: which code does `e2m1_encode` give it,
# and what does it decode to? The check feeds blocks whose largest value sits in that clipped region.
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# Call `mx_shared_exponent(x, n, 2)`, store the exponent plus 127 through the pointer, decode that byte
# with `e8m0_decode`, and for each `i` store `e2m1_encode(x[i] / scale)` as a byte. The decoder multiplies
# `e2m1_decode(codes[i])` by `e8m0_decode(scale_byte)`; a NaN scale falls out of the multiplication.
#
# </details>

# %%
def _mx_hand_blocks() -> list:
    blocks = [[6.0, -3.0, 0.25], [7.5, 0.5], [7.99, -7.99, 0.1], [4.0, 1.0], [0.0] * 7, [1e-38, -2e-38], [1e-30, 3e-31, -5e-32],
              [2e30, -1e30, 3e29], [5.5, 6.0, 6.5, 7.0, 7.5, -7.9], [0.8, 0.9, 0.99, 1.0], [-1.0]]
    return [np.asarray(b, dtype=f32) for b in blocks]


def _mx_random_blocks() -> list:
    """Random blocks of 1 to 32 values at scales from 1e-3 to 40."""
    rng = np.random.default_rng(SEED + 16)
    return [rng.normal(0, mag, n).astype(f32) for n in (1, 2, 5, 17, 31, 32) for mag in (1e-3, 0.05, 40.0) for _ in range(4)]


def _mx_real_blocks() -> list:
    return [b.astype(f32) for b in heavy_tensor(32 * 40).reshape(40, 32)] + [b.astype(f32) for b in gaussian_tensor(32 * 20).reshape(20, 32)]


def _mx_clip_sweep() -> list:
    """Values in and just beyond the clip region of an exact scale 2^j (the block's largest value sits in [4, 8) scales),
    swept over the exponent j."""
    blocks = []
    for j in (-100, -20, -1, 0, 3, 40):
        s = 2.0 ** j
        blocks.append(np.array([4 * s, 5.5 * s, 6 * s, 6.5 * s, 7.5 * s, -7.9 * s, 0.25 * s, -0.75 * s], dtype=f32))
        blocks.append(np.array([float(np.nextafter(f32(8 * s), f32(0))), 1.25 * s, 3.5 * s, 5.0 * s], dtype=f32))
        blocks.append(np.array([4 * s, 0.25 * s, 1.75 * s, 2.5 * s, -3.5 * s, -5.0 * s], dtype=f32))
    return blocks


def _mx_extreme_blocks() -> list:
    """Random blocks whose scale ranges over 60 orders of magnitude, to the edges of the E8M0 byte."""
    rng = np.random.default_rng(SEED + 116)
    return [np.asarray(rng.normal(0, 1, int(rng.integers(1, 33))) * 10.0 ** rng.uniform(-30, 30), dtype=f32) for _ in range(150)]


def _mx_first_bad(blocks: list) -> str:
    got = run_cmd("mxq", [" ".join([str(len(b))] + [hx(v) for v in b]) for b in blocks])
    for b, g in zip(blocks, got):
        sb, codes, _ = ref_mxfp4(b)
        want = [str(int(sb[0]))] + [str(int(c)) for c in codes] + ["238"]
        if g != want:
            return (f"mxfp4_quantise_block on {len(b)} values {b[:4].tolist()}{' ...' if len(b) > 4 else ''} gave scale byte {g[0]} and codes "
                    f"{g[1:]}, expected scale byte {want[0]} and codes {want[1:]} (the last 238 is a guard past the end). The scale byte is "
                    "mx_shared_exponent(x, n, 2) + 127; each code is e2m1_encode(x[i] / scale), which saturates; write exactly n codes")
    return ""


def _mx_quantise_part() -> None:
    why = _mx_first_bad(_mx_hand_blocks())
    assert not why, why
    why = _mx_first_bad(_mx_random_blocks())
    assert not why, why
    why = _mx_first_bad(_mx_real_blocks())
    assert not why, why
    why = _mx_first_bad(_mx_clip_sweep())
    assert not why, why
    why = _mx_first_bad(_mx_extreme_blocks())
    assert not why, why


def _mx_dequantise_first_bad(scale_bytes: list, seed: int) -> str:
    rng = np.random.default_rng(seed)
    cases, want = [], []
    for sb in scale_bytes:
        n = int(rng.integers(1, 33))
        codes = rng.integers(0, 16, n)
        cases.append(" ".join([str(sb), str(n), *map(str, codes.tolist())]))
        with np.errstate(over="ignore"):
            w = (E2M1_VALUES[codes] * ref_e8m0_decode(sb)).astype(f32)
        want.append(np.append(w, f32(12345)))
    for c, g, w in zip(cases, run_cmd("mxdq", cases), want):
        if not same_bits(np.array([unhx(t) for t in g]), w).all():
            return (f"mxfp4_dequantise_block for the case '{' '.join(c.split()[:3])} ...' gave {[float(unhx(t)) for t in g[:4]]} ..., expected "
                    f"{[float(v) for v in w[:4]]} ...: each output is e2m1_decode(code) * e8m0_decode(scale byte), and scale byte 255 makes every output NaN")
    return ""


def _mx_dequantise_part() -> None:
    why = _mx_dequantise_first_bad(list(range(0, 255, 5)) + [1, 2, 127, 128, 130, 253, 254], SEED + 17)
    assert not why, why
    why = _mx_dequantise_first_bad([255, 255, 255], SEED + 117)
    assert not why, why


def _check_mxfp4() -> None:
    _need_selftests("exercise 3", "exercise 4", "exercise 5")
    _mx_quantise_part()
    _mx_dequantise_part()
    print("exercise 5 looks right: scale bytes, codes and decoded values match the reference bit for bit")


if _IS_MAIN:
    _try("exercise 5", _check_mxfp4, needs=("exercise 3", "exercise 4"))


def _rel_err(x, y) -> float:
    """Root of the summed squared error over the summed squared signal, in float64: the error measure this lesson
    reports until exercise 9 asks you to write it."""
    x64, y64 = np.asarray(x, dtype=np.float64).ravel(), np.asarray(y, dtype=np.float64).ravel()
    return float(math.sqrt(np.sum((x64 - y64) ** 2) / np.sum(x64 ** 2)))


def _show_mx_roundtrip() -> None:
    print("the whole tensor, stored in MXFP4 with your encoder, packed to bytes, unpacked and decoded:")
    for name, t in (("Gaussian", gaussian_tensor()), ("heavy-tailed", heavy_tensor())):
        y, rep = roundtrip("mxfp4", t)
        want = ref_mxfp4(t)[2]
        assert same_bits(y, want).all(), f"the {name} tensor does not round-trip to the reference, bit for bit"
        B, _ = _blocks(t, MX_BLOCK)
        blocks_clipped = int((np.frexp(np.abs(B).max(axis=1))[0] * 2 > 1.5).sum())
        assert rep["clipped"] >= blocks_clipped, "every block whose largest value is above 6 scales must clip at least one element"
        print(f"  {name:13s} relative error {100 * _rel_err(t, y):.2f}%   {len(B)} blocks, {blocks_clipped} of them with their largest value above 6 "
              f"scales; the encoder reports {rep['clipped']} elements stored at +-6 that came back smaller")
    print(f"identical to the numpy reference on every one of the {2 * N_TENSOR:,} weights")


if _IS_MAIN:
    _try("MXFP4 round trip", _show_mx_roundtrip, needs=("exercise 1", "exercise 3", "exercise 4", "exercise 5"))

# %% [markdown]
# ## 8. Exercise 6 — the 8-bit float E4M3, in `lesson.cpp`
#
# NVFP4 keeps E2M1 for the weights but stores each block's scale as an 8-bit float, **E4M3**: one sign bit,
# four exponent bits (bias 7) and three mantissa bits. Its mantissa gives about one part in eight, where a
# power of two gives a factor of two, which is what the finer scale buys. Fields S, E, M: with `E = 0` the
# value is subnormal, `2^-6 * (M / 8)`; otherwise `2^(E-7) * (1 + M/8)`. **There is no infinity.** One
# pattern, `E = 15` with `M = 7` in either sign (bytes 0x7F and 0xFF), is NaN, so the largest value is
# 448, byte 0x7E, and byte 0x80 is negative zero.
#
# `e4m3_decode` reads a byte. `e4m3_encode` returns the byte of the nearest value, under rules the check
# enforces: halfway values go to the **even byte**; magnitudes of 448 or more, infinity included,
# **saturate** to 448 (the OCP specification's saturating mode); NaN encodes as 0x7F (this lesson's choice
# of NaN pattern: the specification says only that a NaN converts to a NaN); the sign bit is the sign of
# the input, even for a value that rounds to zero.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# There are only 127 non-negative finite values. Which is simpler to get right for every one of them:
# bit tricks on the float's own bits, or finding the nearest of the 127 by comparing distances? How do
# you break a tie in the second approach, and why is the byte (rather than the value) the thing that is even?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# Handle NaN first, take the sign from `std::signbit`, and return the saturated byte for any magnitude of
# 448 or more. Otherwise scan the bytes 0 to 0x7E, keep the one whose decoded value is nearest in `double`
# arithmetic, and on an exact tie keep the one whose byte is even. Decoding mirrors the field formulas.
#
# </details>

# %%
def _e4m3_decode_part() -> None:
    codes = list(range(-2, 300))
    got = run_cmd("e4d", [str(b) for b in codes])
    for b, g in zip(codes, got):
        assert same_bits(unhx(g[0]), E4M3_VALUES[b & 255]), (
            f"e4m3_decode({b}) gave {float(unhx(g[0])):g} (bits {g[0]}), expected {float(E4M3_VALUES[b & 255]):g}: sign bit 7, exponent bits 6-3 with bias 7, "
            "mantissa bits 2-0, subnormal when the exponent field is 0, NaN for 0x7F and 0xFF, negative zero for 0x80")


def _e4m3_first_bad(probes: np.ndarray) -> str:
    got = [int(g[0]) for g in run_cmd("e4e", [hx(p) for p in probes])]
    want = ref_e4m3_encode(probes)
    bad = [i for i in range(len(probes)) if got[i] != want[i]]
    if not bad:
        return ""
    i = bad[0]
    a = abs(float(probes[i]))
    why = ("NaN encodes as 0x7F" if np.isnan(probes[i]) else "448 and above, infinity included, saturate to 0x7E or 0xFE" if a >= 448 else
           "a value exactly halfway goes to the EVEN byte" if a in set(float((E4M3_MAGS[k].astype(np.float64) + E4M3_MAGS[k + 1]) / 2) for k in range(126)) else
           "keep the sign bit even when the magnitude rounds to zero" if a < 2.0 ** -10 else "the nearest of the 127 values")
    return (f"e4m3_encode({float(probes[i])!r}) gave byte {got[i]} (0x{got[i]:02X}), expected {int(want[i])} (0x{int(want[i]):02X}): {why}. "
            f"({len(bad)} of {len(probes)} probes disagree.)")


def _e4m3_encode_part() -> None:
    probes = _probe_classes(E4M3_MAGS, np.random.default_rng(SEED + 18), 500.0, -12, 3, extra=(447.0, 449.0, 464.0, 1000.0))
    why = _e4m3_first_bad(probes["grid"])
    assert not why, why
    why = _e4m3_first_bad(probes["ties"])
    assert not why, why
    why = _e4m3_first_bad(probes["uniform"])
    assert not why, why
    why = _e4m3_first_bad(probes["log"])
    assert not why, why
    why = _e4m3_first_bad(probes["special"])
    assert not why, why
    why = _e4m3_first_bad(np.array([np.nan, np.uint32(0xFFC00000).view(f32), np.uint32(0x7FC00000).view(f32)], dtype=f32))
    assert not why, why


def _check_e4m3() -> None:
    _need_selftest("exercise 6")
    _e4m3_decode_part()
    _e4m3_encode_part()
    print("exercise 6 looks right: every decode and every halfway, saturating, signed and NaN probe agree with the reference")


if _IS_MAIN:
    _try("exercise 6", _check_e4m3)


def _show_scale_precision() -> None:
    """How closely each scale format can store the scale a block wants, measured with your functions."""
    rng = np.random.default_rng(SEED + 19)
    n_scales, lo, hi = 20000, 0.02, 400.0
    wanted = f32(10.0 ** rng.uniform(np.log10(lo), np.log10(hi), n_scales))
    e4 = np.array([unhx(t[0]) for t in run_cmd("e4d", [str(int(t[0])) for t in run_cmd("e4e", [hx(v) for v in wanted])])], dtype=np.float64)
    expo = [int(t[0]) for t in run_cmd("shx", [" ".join(["1", "0", hx(v)]) for v in wanted])]
    e8 = np.array([unhx(t[0]) for t in run_cmd("e8d", [str(x + 127) for x in expo])], dtype=np.float64)
    w64 = wanted.astype(np.float64)
    r4, r8 = np.abs(e4 / w64 - 1.0), np.abs(e8 / w64 - 1.0)
    print(f"storing {n_scales:,} scales between {lo:g} and {hi:g} (about {math.log10(hi / lo):.1f} decades), the relative error of the stored scale:")
    print(f"  E4M3, rounded to nearest        mean {100 * r4.mean():5.2f}%   worst {100 * r4.max():5.2f}%   distinct stored scales {len(np.unique(e4))}")
    print(f"  E8M0, rounded down to 2^X       mean {100 * r8.mean():5.2f}%   worst {100 * r8.max():5.2f}%   distinct stored scales {len(np.unique(e8))}")
    print("a block's scale is only as good as this: an E8M0 scale can be up to half the scale the block wanted, and a block scaled "
          "too small clips, a block scaled too large wastes codes")


if _IS_MAIN:
    _try("scale precision", _show_scale_precision, needs=("exercise 4", "exercise 6"))

# %% [markdown]
# ## 9. Exercise 7 — an NVFP4 tensor, in `lesson.cpp`
#
# NVFP4 has **two levels of scale**. The 4-bit codes are E2M1, as in MXFP4, but a block is 16 weights, its
# scale is an E4M3 byte (so it is not restricted to powers of two), and the tensor carries one float. The
# second level exists because E4M3 spans only about 2^-9 to 448: a tensor whose weights are all around
# 0.01 would need block scales far below that, so the tensor scale first moves the whole tensor so that its
# largest block scale lands exactly on E4M3's maximum.
#
# NVIDIA's NVFP4 pretraining paper gives the recipe (its appendix B, quoted in `claims.yaml`), and the
# comment above `nvfp4_quantise` in `lesson.cpp` spells out every single-precision operation in order,
# because the check is bit for bit: `s_enc = 2688 / amax_x` (2688 is 6 times 448), `s_dec = 1 / s_enc`;
# per block `s_dec_b = amax_b / 6`, the stored byte is `e4m3_encode(s_dec_b * s_enc)`, and each weight is
# multiplied by `1 / (decoded scale * s_dec)` before E2M1 encoding. Decoding multiplies the code's
# value by the block scale, then by the tensor scale, and it takes the scale byte as stored: a byte with its sign bit set
# (0x80 and above) is a negative scale, and 0x7F and 0xFF are NaN, so the decoder takes no absolute value and masks nothing.
# The scale byte is worked out in exactly the order above, the block's largest magnitude divided by 6 first and then
# multiplied by `s_enc`: other orders of the same arithmetic (multiply first, multiply by a reciprocal of 6, divide by
# `s_dec`, work in double) round differently in the last place and sometimes choose the neighbouring byte, and the check
# includes tensors built to show it. Two corner cases are fixed too: an all-zero tensor,
# and a block whose scale byte comes out as zero.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# The scale the block *stores* is not the scale the weights are divided by: the encoder divides by the
# value the byte actually decodes to, so that the stored scale and the used scale agree. Which function
# turns the byte back into a float? And what do you do with a block whose byte decodes to zero, where
# `1 / (0 * s_dec)` is infinite?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# First pass: the tensor's largest magnitude, then `s_enc` and `s_dec` (both 1 when the tensor is all
# zeros). Second pass, block by block: the block's largest magnitude, `s_dec_b`, the byte from
# `e4m3_encode`, the decoded scale `sb`; if `sb` is zero write zero codes, otherwise form `s_enc_b` and encode
# each weight. Return `s_dec`. The decoder is one expression per weight, with the block index `i / 16`.
#
# </details>

# %%
# (amax, x) pairs for which x * (1 / (sb * s_dec)) and x / (sb * s_dec) give different E2M1 codes when a tensor [amax, x, 0, ...]
# is encoded (found by search). The exercise says to multiply by the reciprocal.
NV_RECIPROCAL_PAIRS = [(10.0, 0.416666716337204), (0.05000000074505806, 0.0062500000931322575), (1.0, 0.2916666567325592), (1.0, 0.5833333134651184), (0.12300000339746475, 0.02562500163912773), (0.12300000339746475, 0.05125000327825546), (0.12300000339746475, 0.10250000655651093), (2.0, 0.5833333134651184), (2.0, 1.1666666269302368), (45.0, 5.624999523162842), (45.0, 9.375), (45.0, 13.124999046325684), (45.0, 18.75), (45.0, 26.249998092651367), (45.0, 37.5)]


# (amax_x, amax_b) pairs for which the stated order of the scale-byte step, e4m3_encode((amax_b / 6) * s_enc), and each other order
# of the same arithmetic (amax_b * s_enc / 6, amax_b * (1 / 6) * s_enc, amax_b / 6 / s_dec, amax_b / (6 * s_dec), a double-precision
# product rounded once) give different scale bytes when the tensor [amax_x, 0, ..., 0, amax_b, 0, ..., 0] (two blocks) is encoded
# (found by search: each sits on, or within two float32 steps of, a halfway point between two E4M3 values). The exercise gives the order.
NV_SCALE_PAIRS = [(7.882173667894676e-05, 1.1964014447585214e-05), (2.4556162357330322, 0.017129020765423775), (4.529163197730668e-05, 7.683401236135978e-06), (3.436174301896244e-05, 1.7641070826357463e-06), (1.4029725434738793e-06, 3.9145440666743525e-08), (0.015908528119325638, 0.004829374607652426), (4.098541467101313e-05, 1.5369530956377275e-05), (21.964914321899414, 0.047496672719717026), (3.647358244052157e-05, 2.7355186830391176e-05), (3.436174301896244e-05, 1.764107196322584e-06), (4.695662573794834e-05, 1.2158412573626265e-05), (21.964914321899414, 0.047496676445007324)]


def _nv_hand_tensors() -> list:
    tensors = [[6.0, -3.0, 1.5] + [0.0] * 13, [0.0] * 20, [-0.0] * 3, [1.0], [-5.0], [-448.0 * 6], [0.5] * 40, [7.0] * 16 + [-7.0] * 16,
               [2688.0, 1.0] * 8, [1e19, -1e-19] * 9]
    return [np.asarray(t, dtype=f32) for t in tensors]


def _nv_random_tensors() -> list:
    """Gaussian and heavy-tailed prefixes of 1 to 257 values, scaled by 10^-6, 1 and 10^5."""
    g, h = gaussian_tensor(1024), heavy_tensor(1024)
    tensors = []
    for n in (1, 15, 16, 17, 31, 32, 33, 50, 100, 257):
        for src in (g, h):
            for k in (-7, -6, 0, 5, 6):
                tensors.append((src[:n] * 10.0 ** k).astype(f32))
    return tensors


def _nv_small_block_tensors() -> list:
    """Blocks far smaller than the tensor's largest: scale bytes in the E4M3 subnormal range and exactly zero."""
    rng = np.random.default_rng(SEED + 20)
    tensors = [[1000.0] + [0.0] * 15 + (rng.normal(0, 1e-5, 16)).tolist() + (rng.normal(0, 3e-3, 16)).tolist() + (rng.normal(0, 1.0, 16)).tolist(),
               [300.0, 1.0] * 8 + (rng.normal(0, 1e-9, 16)).tolist() + [0.0] * 16]
    tensors += [[1000.0] + [0.0] * 15 + rng.normal(0, 10.0 ** e, 16).tolist() + rng.normal(0, 1, 16).tolist() for e in (-3, -4, -5, -7, -9)]
    return [np.asarray(t, dtype=f32) for t in tensors]


def _nv_element_tensors() -> list:
    return [np.asarray([a, x] + [0.0] * 14, dtype=f32) for a, x in NV_RECIPROCAL_PAIRS]


def _nv_scale_tensors() -> list:
    return [np.asarray([a] + [0.0] * 15 + [x] + [0.0] * 15, dtype=f32) for a, x in NV_SCALE_PAIRS]


def _nv_fat_tail_tensors() -> list:
    rng = np.random.default_rng(SEED + 120)
    return [(rng.standard_t(2, 50) * 0.01).astype(f32) for _ in range(6)]


def _nv_first_bad(tensors: list) -> str:
    got = run_cmd("nvq", [" ".join([str(len(t))] + [hx(v) for v in t]) for t in tensors])
    for t, g in zip(tensors, got):
        s_dec, sbytes, codes, _ = ref_nvfp4(t)
        want = [hx(s_dec)] + [str(int(b)) for b in sbytes] + ["238"] + [str(int(c)) for c in codes] + ["238"]
        if g != want:
            nb = len(sbytes)
            where = ("the tensor scale (s_dec = 1 / (2688 / amax))" if g[0] != want[0] else
                     "a scale byte (e4m3_encode((amax_b / 6) * s_enc), nearest, halves to even, in exactly that order)" if g[1:nb + 2] != want[1:nb + 2] else
                     "a code (e2m1_encode(x * s_enc_b) with s_enc_b = 1 / (sb * s_dec), sb the DECODED scale byte)")
            return (f"nvfp4_quantise on {len(t)} values {t[:3].tolist()}{' ...' if len(t) > 3 else ''}: the first difference is in {where}. "
                    f"Got tensor scale bits {g[0]}, scale bytes {g[1:nb + 1]} and codes {g[nb + 2:nb + 8]} ..., expected {want[0]}, "
                    f"{want[1:nb + 1]} and {want[nb + 2:nb + 8]} ... (a 238 after each list is a guard past its end). "
                    "Every operation is single precision, in the order of the comment above the function")
    return ""


def _nv_quantise_part() -> None:
    why = _nv_first_bad(_nv_hand_tensors())
    assert not why, why
    why = _nv_first_bad(_nv_random_tensors())
    assert not why, why
    why = _nv_first_bad(_nv_small_block_tensors())
    assert not why, why
    why = _nv_first_bad(_nv_element_tensors())
    assert not why, why
    why = _nv_first_bad(_nv_scale_tensors())
    assert not why, why
    why = _nv_first_bad(_nv_fat_tail_tensors())
    assert not why, why


def _nv_dequantise_first_bad(cases: list) -> str:
    """cases: (tensor scale, scale bytes, codes); the decoded value is (e2m1(code) * e4m3(byte of block i / 16)) * tensor scale."""
    lines, want = [], []
    for ts, sbytes, codes in cases:
        n = len(codes)
        lines.append(" ".join([hx(ts), str(n), *map(str, sbytes), *map(str, codes)]))
        with np.errstate(over="ignore", invalid="ignore"):
            w = ((E2M1_VALUES[np.asarray(codes)] * E4M3_VALUES[np.asarray(sbytes)[np.arange(n) // 16]]) * f32(ts)).astype(f32)
        want.append(np.append(w, f32(12345)))
    for c, g, w in zip(lines, run_cmd("nvdq", lines), want):
        if not same_bits(np.array([unhx(t) for t in g]), w).all():
            return ("nvfp4_dequantise must give (e2m1_decode(code) * e4m3_decode(scale byte of block i / 16)) * tensor scale, "
                    "two single-precision multiplications in that order, and write nothing past n (a scale byte can be negative: 0x80 and above, "
                    f"and 0x7F and 0xFF are NaN); the case '{' '.join(c.split()[:2])} ...' differs")
    return ""


def _nv_dequantise_part() -> None:
    rng = np.random.default_rng(SEED + 21)
    codes16 = list(range(16))
    positive = [(f32(10.0 ** rng.uniform(-6, 2)), [b], codes16) for b in (0, 1, 7, 8, 56, 100, 125, 126)]
    why = _nv_dequantise_first_bad(positive)
    assert not why, why
    signed = [(f32(10.0 ** rng.uniform(-6, 2)), [b], codes16) for b in (127, 128, 129, 192, 253, 254, 255)]
    why = _nv_dequantise_first_bad(signed)
    assert not why, why
    mixed = []
    for n in (1, 2, 15, 16, 17, 40, 64, 96):
        nb = -(-n // 16)
        mixed.append((f32(10.0 ** rng.uniform(-8, 6)), rng.integers(0, 256, nb).tolist(), rng.integers(0, 16, n).tolist()))
    why = _nv_dequantise_first_bad(mixed)
    assert not why, why


def _check_nvfp4() -> None:
    _need_selftests("exercise 3", "exercise 6", "exercise 7")
    _nv_quantise_part()
    _nv_dequantise_part()
    print("exercise 7 looks right: tensor scales, block scales, codes and decoded values match the reference bit for bit")


if _IS_MAIN:
    _try("exercise 7", _check_nvfp4, needs=("exercise 3", "exercise 6"))


def _show_nv_roundtrip() -> None:
    print("the whole tensor, stored in NVFP4 with your encoder, packed to bytes, unpacked and decoded:")
    for name, t in (("Gaussian", gaussian_tensor()), ("heavy-tailed", heavy_tensor())):
        y, rep = roundtrip("nvfp4", t)
        assert same_bits(y, ref_nvfp4(t)[3]).all(), f"the {name} tensor does not round-trip to the reference, bit for bit"
        print(f"  {name:13s} relative error {100 * _rel_err(t, y):.2f}%   {rep['top_codes']} weights stored at +-6, {rep['clipped']} of them smaller on the way back")
    print(f"identical to the numpy reference on every one of the {2 * N_TENSOR:,} weights")


