# %% [markdown]
# ### Checkpoint: all three formats, through the packed bytes
#
# One more check before the measurements, because everything after it rests on it. `roundtrip` runs **your**
# functions on a whole array: it cuts the array into blocks (the last one short), quantises each, packs the
# codes two to a byte, counts the bytes written, then unpacks and decodes from those bytes alone. The check
# below compares the decoded values with the numpy reference bit for bit, and the byte counts with what each
# format must store: INT4 one nibble per weight and a 4-byte float per block of 32, MXFP4 one nibble per weight
# and one byte per block of 32, NVFP4 one nibble per weight, one byte per block of 16 and a 4-byte tensor scale.
# It needs exercises 1 to 7, and the board at the foot of the notebook lists it after the exercises.

# %%
def _stored_bytes(fmt: str, n: int) -> tuple:
    """What each format must store for n weights, from its definition (written here for the check, not by your encoder):
    (code bytes, scale bytes, tensor scale bytes)."""
    ceil = lambda a, b: -(-a // b)
    if fmt == "int4":
        return ceil(n, 2), 4 * ceil(n, INT4_BLOCK), 0
    if fmt == "mxfp4":
        return ceil(n, 2), ceil(n, MX_BLOCK), 0
    return ceil(n, 2), ceil(n, NV_BLOCK), 4


def _roundtrip_part() -> None:
    rng = np.random.default_rng(SEED + 22)
    for n, scale in ((97, 0.05), (480, 3.0), (256, 1e-4)):
        x = rng.normal(0, scale, n).astype(f32)
        x[::40] *= f32(6.0)
        y, rep = roundtrip("int4", x)
        assert same_bits(y, ref_int4(x)[2]).all() and (rep["code_bytes"], rep["scale_bytes"], rep["tensor_scale_bytes"]) == _stored_bytes("int4", n), (
            f"n = {n}: INT4 stored through packed bytes must decode to the reference values, with {_stored_bytes('int4', n)[0]} code bytes and "
            f"{_stored_bytes('int4', n)[1]} scale bytes (got {rep['code_bytes']} and {rep['scale_bytes']})")
        y, rep = roundtrip("mxfp4", x)
        assert same_bits(y, ref_mxfp4(x)[2]).all() and (rep["code_bytes"], rep["scale_bytes"], rep["tensor_scale_bytes"]) == _stored_bytes("mxfp4", n), (
            f"n = {n}: MXFP4 stored through packed bytes must decode to the reference values, with {_stored_bytes('mxfp4', n)[0]} code bytes and "
            f"{_stored_bytes('mxfp4', n)[1]} scale bytes and no tensor scale (got {rep['code_bytes']}, {rep['scale_bytes']} and {rep['tensor_scale_bytes']})")
        y, rep = roundtrip("nvfp4", x)
        assert same_bits(y, ref_nvfp4(x)[3]).all() and (rep["code_bytes"], rep["scale_bytes"], rep["tensor_scale_bytes"]) == _stored_bytes("nvfp4", n), (
            f"n = {n}: NVFP4 stored through packed bytes must decode to the reference values, with {_stored_bytes('nvfp4', n)[0]} code bytes, "
            f"{_stored_bytes('nvfp4', n)[1]} scale bytes and a 4-byte tensor scale (got {rep['code_bytes']}, {rep['scale_bytes']} and {rep['tensor_scale_bytes']})")


def _check_roundtrip() -> None:
    _need_selftests("exercise 1", "exercise 2", "exercise 3", "exercise 4", "exercise 5", "exercise 6", "exercise 7")
    _roundtrip_part()
    print("the round trip looks right: all three formats decode, from the packed bytes alone, to the reference values, with the byte counts the formats require")


if _IS_MAIN:
    _try("round trip", _check_roundtrip, needs=("exercise 1", "exercise 2", "exercise 3", "exercise 4", "exercise 5", "exercise 6", "exercise 7"))

# %% [markdown]
# ## 10. Exercise 8 — bits per weight, from the bytes
#
# "4-bit" is a name, not a measurement. What a format costs is the bytes it really stores, counted over
# every stream it writes: the packed codes, the scales, and (for NVFP4) the one float per tensor. Write
# `bits_per_weight` so that it takes those byte counts, as `roundtrip` reports them, and returns the
# storage per weight **as an exact `fractions.Fraction`**: `8 * (all the bytes) / n_weights`. A float
# would give 4.25 for MXFP4 on a whole number of blocks and a rounded decimal almost everywhere else;
# a fraction keeps the arithmetic exact, so two formats can be compared without a tolerance.
#
# Worked example: 32 weights stored in 16 code bytes and 1 scale byte cost `8 * 17 / 32 = 17/4` bits
# each. `n_weights` is at least 1.
#
# <details><summary>Hint 1 — what to think about</summary>
#
# Which three byte counts does a format have, and which of them are zero for MXFP4? Why is a Python float
# the wrong type to return when the answer is `17/4`, and what does `Fraction(8 * 17, 32)` print?
#
# </details>
# <details><summary>Hint 2 — the approach in words</summary>
#
# Add the three byte counts, multiply by 8 to get bits, and build the fraction over `n_weights` from two
# integers, so that no float is ever formed.
#
# </details>

# %%
def bits_per_weight(n_weights: int, code_bytes: int, scale_bytes: int, tensor_scale_bytes: int = 0) -> Fraction:
    """Storage per weight in bits, as an exact fraction: 8 * (code_bytes + scale_bytes + tensor_scale_bytes) / n_weights.

    Worked example: bits_per_weight(32, 16, 1) == Fraction(17, 4).
    Returns a fractions.Fraction (not a float).
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_bits_per_weight() -> None:
    got = bits_per_weight(32, 16, 1)
    assert isinstance(got, Fraction), (f"bits_per_weight returned a {type(got).__name__}: return a fractions.Fraction built from two integers, "
                                       "Fraction(8 * bytes, n_weights), so that 17/4 stays exact")
    assert got == Fraction(17, 4), f"bits_per_weight(32, 16, 1) gave {got}, expected 17/4: eight bits per byte, over every byte stored"
    for fmt in ("int4", "mxfp4", "nvfp4"):
        for n in (1, 2, 15, 16, 17, 32, 33, 100, 1001, 4096, 49152):
            code, scale, tensor = _stored_bytes(fmt, n)
            got = bits_per_weight(n, code, scale, tensor)
            want = Fraction(8 * (code + scale + tensor), n)
            assert isinstance(got, Fraction) and got == want, (
                f"{fmt} with {n} weights stores {code} code bytes, {scale} scale bytes and {tensor} tensor-scale bytes: expected exactly {want}, "
                f"got {got}. Count every stream, including the tensor scale of NVFP4 (it is zero for the other two), over n_weights")
    assert bits_per_weight(10, 5, 0) == Fraction(4, 1) and bits_per_weight(7, 4, 1, 4) == Fraction(72, 7) and bits_per_weight(5, 3, 2) == Fraction(8, 1), (
        "the third and fourth arguments are bytes too: add them before multiplying by 8, and keep the answer a fraction; "
        "the tensor-scale bytes are optional and count as zero when left out")
    rng = np.random.default_rng(SEED + 30)
    for _ in range(60):
        n = int(rng.integers(1, 100000))
        c, s, t = (int(v) for v in rng.integers(0, 60000, 3))
        got = bits_per_weight(n, c, s, t)
        assert isinstance(got, Fraction) and got == Fraction(8 * (c + s + t), n), (
            f"n = {n} weights in {c} + {s} + {t} bytes: expected exactly {Fraction(8 * (c + s + t), n)}, got {got!r}. "
            "Build the fraction from integers whatever their size, 8 * (all the bytes) over n_weights")
    print("exercise 8 looks right: every format and size, as an exact fraction")


if _IS_MAIN:
    _try("exercise 8", _check_bits_per_weight)


def _show_storage() -> None:
    n = N_TENSOR + 17        # not a multiple of any block: the last block is short, and every stream pays for it
    x = gaussian_tensor(n)
    print(f"{n:,} weights, stored with your encoders and packed; the bytes are counted from what was written:")
    print(f"  {'format':8s} {'code bytes':>11} {'scale bytes':>12} {'tensor scale':>13} {'bits per weight':>16}")
    for fmt in ("int4", "mxfp4", "nvfp4"):
        _y, rep = roundtrip(fmt, x)
